/* resolver(): recálculo INDEPENDIENTE de la plantilla */
CB.gen.problemas.resolver = function (subtipo, d) {
  const x = d[0], y = d[1];
  switch (subtipo) {
    case 'CAMBIO_1':      return x + y;
    case 'CAMBIO_2':      return x - y;
    case 'COMBINACION_1': return x + y;
    case 'COMBINACION_2': return x - y;
    case 'COMPARACION_1': return x - y;
    case 'COMPARACION_2': return x - y;
    case 'CAMBIO_3':      return y - x;
    case 'CAMBIO_4':      return x - y;
    case 'COMPARACION_3': return x + y;
    case 'COMPARACION_4': return x - y;
    case 'IGUALACION_1':  return x - y;
    case 'IGUALACION_2':  return x - y;
    case 'CAMBIO_5':      return y - x;
    case 'CAMBIO_6':      return y + x;
    case 'COMPARACION_5': return x - y;
    case 'COMPARACION_6': return x + y;
    case 'IGUALACION_3':  return x - y;
    case 'IGUALACION_4':  return x - y;
    case 'IGUALACION_5':  return x + y;
    case 'IGUALACION_6':  return x - y;
    default: return null;
  }
};

/* Elección de números por subtipo, respetando el techo del trimestre */
CB.gen.problemas.numeros = function (subtipo, rng, D, techo) {
  let max = Math.min(techo || 99, (D === 1) ? 20 : (D === 2 ? 60 : techo || 99));
  if (max < 6) max = 6;
  let a, b, c, k = 0;

  switch (subtipo) {
    case 'CAMBIO_1': case 'COMBINACION_1': case 'COMPARACION_3': case 'COMPARACION_6':
      do { k++; a = CB.util.ent(rng, 2, max); b = CB.util.ent(rng, 1, max); }
      while (a + b > (techo || 99) && k < 40);
      return [a, b];

    case 'CAMBIO_6': case 'IGUALACION_5':
      do { k++; b = CB.util.ent(rng, 1, Math.floor(max / 2)); c = CB.util.ent(rng, 2, max); }
      while (c + b > (techo || 99) && k < 40);
      return [c, b];

    case 'CAMBIO_3': case 'CAMBIO_5':
      /* El segundo dato es el mayor: la respuesta nunca es negativa. */
      a = CB.util.ent(rng, 1, Math.max(2, max - 2));
      c = CB.util.ent(rng, a + 1, max);
      return [a, c];

    default:
      /* Todos los de resta: el primero SIEMPRE ≥ el segundo (invariante 2). */
      a = CB.util.ent(rng, 3, max);
      b = CB.util.ent(rng, 1, a);
      return [a, b];
  }
};

/* Dato sobrante (§9.4) */
CB.gen.problemas.datoSobrante = function (datos, respuesta, rng, techo) {
  const a = datos[0], b = datos[1];
  let k = 0, c;
  while (k < 40) {
    k++;
    c = CB.util.ent(rng, 1, Math.min(techo || 99, 40));
    if (c === a || c === b || c === respuesta) continue;
    if (a + c === respuesta || a - c === respuesta) continue;
    if (b + c === respuesta || b - c === respuesta) continue;
    if (c + a === respuesta || c - a === respuesta) continue;
    if (c + b === respuesta || c - b === respuesta) continue;
    return c;
  }
  return null;
};

/* El validador de lectura fácil — INVARIANTE 7 */

CB.gen.problemas.SUBORDINANTES = ['si', 'cuando', 'mientras', 'aunque', 'porque'];
/* «que» solo se admite en las comparativas: más que / menos que. */
CB.gen.problemas.ANTES_DE_QUE = ['más', 'menos', 'tantos', 'tantas'];

/* Formas que DEBEN llevar tilde en la acepción que usa el juego. Si aparece la
   forma sin tilde, el test falla: es material escolar. */
CB.gen.problemas.EXIGEN_TILDE = {
  'mas': 'más', 'numero': 'número', 'cuantos': 'cuántos', 'cuantas': 'cuántas',
  'cuanto': 'cuánto', 'despues': 'después', 'que': null, 'cual': 'cuál',
  'como': null, 'tenia': 'tenía'
};

CB.gen.problemas.validacion = {
  excedePalabras: function (textos, limite) {
    return textos.some(function (texto) {
      return CB.util.palabras(texto).length > limite;
    });
  },

  excedeAncho: function (lineas, limite) {
    return lineas.some(function (linea) { return linea.length > limite; });
  },

  tieneSubordinacion: function (palabras) {
    return palabras.some(function (palabra, indice) {
      if (CB.gen.problemas.SUBORDINANTES.indexOf(palabra) !== -1) return true;
      if (palabra !== 'que') return false;
      const anterior = indice > 0 ? palabras[indice - 1] : '';
      return CB.gen.problemas.ANTES_DE_QUE.indexOf(anterior) === -1;
    });
  },

  faltaTilde: function (palabras) {
    return palabras.some(function (palabra) {
      return !!CB.gen.problemas.EXIGEN_TILDE[palabra];
    });
  },

  repiteSujeto: function (frases) {
    return frases.some(function (frase, indice) {
      if (indice === 0) return false;
      const anterior = CB.util.palabras(frases[indice - 1])[0];
      const actual = CB.util.palabras(frase)[0];
      return !!(anterior && actual && anterior === actual && /^[A-ZÁÉÍÓÚÑ]/.test(anterior));
    });
  },

  fueraDeLista: function (palabras) {
    const invalida = palabras.find(function (palabra) {
      if (/^\d+$/.test(palabra)) return false;
      return !CB.datos.enListaBlanca(palabra);
    });
    return invalida || null;
  }
};

CB.gen.problemas.validar = function (item) {
  const motivos = [];
  const frases = item.frases || [];
  const texto = frases.join(' ');

  /* 1. Número de frases y forma de la pregunta */
  if (frases.length > 3) motivos.push('frases');
  if (!frases.length) { motivos.push('frases'); return { ok: false, motivos: motivos }; }

  const ultima = frases[frases.length - 1];
  if (ultima.indexOf('¿') !== 0 || ultima.charAt(ultima.length - 1) !== '?') {
    motivos.push('pregunta');
  }
  if (CB.util.palabras(ultima).length > 8) motivos.push('preguntaLarga');

  /* 2. Longitud */
  if (CB.gen.problemas.validacion.excedePalabras(frases, 12)) motivos.push('fraseLarga');
  if (CB.util.palabras(texto).length > 25) motivos.push('total');

  /* 3. Ancho de línea, con el MISMO algoritmo que usa la interfaz */
  const lineas = CB.util.cortarLineas(texto, 34);
  if (CB.gen.problemas.validacion.excedeAncho(lineas, 34)) motivos.push('ancho');
  if (lineas.length > 5) motivos.push('demasiadasLineas');

  /* 4. Datos numéricos */
  const numeros = texto.match(/\d+/g) || [];
  const maxDatos = item.datoSobrante ? 3 : 2;
  if (numeros.length > maxDatos) motivos.push('datos');

  /* 5. Subordinación prohibida */
  const palabras = CB.util.palabras(texto.toLowerCase().replace(/[¿?.,!¡]/g, ''));
  if (CB.gen.problemas.validacion.tieneSubordinacion(palabras)) motivos.push('subordinacion');

  /* 6. Tildes obligatorias */
  if (CB.gen.problemas.validacion.faltaTilde(palabras)) motivos.push('tilde');
  /* Toda exclamación abre con ¡ y cierra con !; toda interrogación con ¿ y ? */
  if (texto.indexOf('!') !== -1 && texto.indexOf('¡') === -1) motivos.push('signos');
  if (texto.indexOf('?') !== -1 && texto.indexOf('¿') === -1) motivos.push('signos');

  /* 7. Sujeto explícito repetido en frases consecutivas */
  if (CB.gen.problemas.validacion.repiteSujeto(frases)) motivos.push('sujetoRepetido');

  /* 8. Lista blanca */
  const fueraDeLista = CB.gen.problemas.validacion.fueraDeLista(palabras);
  if (fueraDeLista) motivos.push('listaBlanca:' + fueraDeLista);

  /* 9. Rango de la respuesta */
  if (!(item.respuesta >= 0 && item.respuesta <= 999)) motivos.push('rango');

  return { ok: motivos.length === 0, motivos: motivos };
};

/* PROBLEMAS_SEGUROS: 12 enunciados fijos validados a mano */
CB.gen.problemas.PROBLEMAS_SEGUROS = [
  { subtipo: 'CAMBIO_1', frases: ['Ana tiene 12 cromos.', 'Después gana 5 cromos.', '¿Cuántos cromos tiene ahora?'], datos: [12, 5], respuesta: 17, operacion: '+' },
  { subtipo: 'CAMBIO_2', frases: ['Leo tiene 15 canicas.', 'Después regala 6 canicas.', '¿Cuántas canicas le quedan?'], datos: [15, 6], respuesta: 9, operacion: '-' },
  { subtipo: 'COMBINACION_1', frases: ['Sara tiene 8 fresas.', 'Hugo tiene 7 fresas.', '¿Cuántas fresas tienen en total?'], datos: [8, 7], respuesta: 15, operacion: '+' },
  { subtipo: 'COMBINACION_2', frases: ['Entre Marta y Bruno tienen 20 globos.', 'Marta tiene 12.', '¿Cuántos globos tiene Bruno?'], datos: [20, 12], respuesta: 8, operacion: '-' },
  { subtipo: 'COMPARACION_1', frases: ['Julia tiene 14 pegatinas.', 'Pablo tiene 9 pegatinas.', '¿Cuántas pegatinas más tiene Julia?'], datos: [14, 9], respuesta: 5, operacion: '-' },
  { subtipo: 'COMPARACION_2', frases: ['Laia tiene 18 hojas.', 'Marc tiene 11 hojas.', '¿Cuántas hojas menos tiene Marc?'], datos: [18, 11], respuesta: 7, operacion: '-' },
  { subtipo: 'CAMBIO_3', frases: ['Noa tenía 10 conchas.', 'Ahora tiene 16 conchas.', '¿Cuántas conchas ha ganado?'], datos: [10, 16], respuesta: 6, operacion: '-' },
  { subtipo: 'CAMBIO_4', frases: ['Pau tenía 21 piedras.', 'Ahora tiene 13 piedras.', '¿Cuántas piedras ha perdido?'], datos: [21, 13], respuesta: 8, operacion: '-' },
  { subtipo: 'COMPARACION_3', frases: ['Emma tiene 9 flores.', 'Jan tiene 4 más.', '¿Cuántas flores tiene Jan?'], datos: [9, 4], respuesta: 13, operacion: '+' },
  { subtipo: 'COMPARACION_4', frases: ['Iris tiene 17 gemas.', 'Nil tiene 5 menos.', '¿Cuántas gemas tiene Nil?'], datos: [17, 5], respuesta: 12, operacion: '-' },
  { subtipo: 'IGUALACION_1', frases: ['Alba tiene 13 setas.', 'Iker tiene 6 setas.', '¿Cuántas le faltan a Iker?'], datos: [13, 6], respuesta: 7, operacion: '-' },
  { subtipo: 'COMPARACION_5', frases: ['Nora tiene 12 cromos.', 'Tiene 5 más que Mario.', '¿Cuántos cromos tiene Mario?'], datos: [12, 5], respuesta: 7, operacion: '-' }
];

/* Generación */
CB.gen.problemas.generarSubtipo = function (subtipo, rng, D, ctx) {
  ctx = ctx || {};
  /* El techo del problema se queda en 999 aunque el curso llegue al millón:
     el validador de lectura fácil exige respuesta ≤ 999, y sin este tope un
     curso alto agotaba los 20 intentos y servía SIEMPRE el problema de
     respaldo. En los problemas la dificultad vive en la estructura, no en el
     tamaño del número (3.1.0). */
  const techo = Math.min(ctx.techo || 99, 999);
  const conSobrante = !!ctx.datoSobrante;
  let intentos = 0, item;

  while (intentos < 20) {
    intentos++;
    const act = CB.gen.problemas.elegirActores(rng, ctx.bolsas);
    if (ctx.bolsas) ctx.bolsas = act.bolsas;

    const verbos = CB.gen.problemas.VERBOS_PROBLEMA[act.obj.cat];
    const vg = CB.util.elegir(rng, verbos.ganar);
    const vp = CB.util.elegir(rng, verbos.perder);

    const d = CB.gen.problemas.numeros(subtipo, rng, D, techo);
    const plantilla = CB.gen.problemas.PLANTILLAS[subtipo];
    if (!plantilla) break;

    const base = plantilla(d[0], d[1], act, vg, vp);
    if (base.respuesta < 0 || base.respuesta > 999) continue;

    item = {
      subtipo: subtipo,
      formato: 'teclado',            /* SIEMPRE teclado en primer intento (§9.5) */
      frases: base.frases,
      enunciado: base.frases.join(' '),
      datos: base.datos,
      respuesta: base.respuesta,
      operacion: base.operacion,
      destreza: CB.gen.problemas.DESTREZA(subtipo),
      objeto: act.obj,
      actores: [act.n1, act.n2],
      expr: subtipo + '_' + base.datos.join('_'),
      diagnostico: true,
      datoSobrante: false
    };

    if (conSobrante) {
      const c = CB.gen.problemas.datoSobrante(base.datos, base.respuesta, rng, techo);
      if (c != null) {
        item.datoSobrante = true;
        item.numeroSobrante = c;
        item.frases = [base.frases[0], base.frases[1],
                       base.frases[2]];
        /* El dato sobrante se inserta como una coletilla de la 2.ª frase, sin
           subordinación y sin pasar de 12 palabras. */
        const extra = 'También tiene ' + c + ' ' + act.obj.plur + ' de otro color.';
        if (CB.util.palabras(extra).length <= 12) {
          item.frases = [base.frases[0], extra, base.frases[2]];
          item.datos = base.datos.slice();
        } else {
          item.datoSobrante = false;
        }
        item.enunciado = item.frases.join(' ');
      }
    }

    const v = CB.gen.problemas.validar(item);
    if (v.ok) { item.validado = true; return item; }
    item.motivos = v.motivos;
  }

  /* Ningún intento ha validado: se sirve un enunciado seguro. */
  const seguro = CB.gen.problemas.PROBLEMAS_SEGUROS.filter(function (p) {
    return p.subtipo === subtipo;
  })[0] || CB.gen.problemas.PROBLEMAS_SEGUROS[0];

  return {
    subtipo: seguro.subtipo,
    formato: 'teclado',
    frases: seguro.frases.slice(),
    enunciado: seguro.frases.join(' '),
    datos: seguro.datos.slice(),
    respuesta: seguro.respuesta,
    operacion: seguro.operacion,
    destreza: CB.gen.problemas.DESTREZA(seguro.subtipo),
    expr: 'seguro_' + seguro.subtipo,
    diagnostico: true,
    datoSobrante: false,
    deRespaldo: true
  };
};

/* siguienteSubtipo(): deuda de cobertura PONDERADA (§9.2) */
CB.gen.problemas.disponibles = function (perfil) {
  const trimestre = (perfil && perfil.trimestreDeducido) ? perfil.trimestreDeducido : 1;
  let out = CB.gen.problemas.NUCLEAR.slice(), i, p, nuclearOk = true;

  /* Los INTERMEDIOS solo desde T2 y solo con ≥80 % en los nucleares. */
  let aciertos = 0, intentos = 0;
  for (i = 0; i < CB.gen.problemas.NUCLEAR.length; i++) {
    p = (perfil && perfil.problemas) ? perfil.problemas[CB.gen.problemas.NUCLEAR[i]] : null;
    if (p) { aciertos += p.aciertos || 0; intentos += p.intentos || 0; }
  }
  nuclearOk = (intentos >= 6) && ((aciertos / intentos) >= 0.8);

  if (trimestre >= 2 && nuclearOk) out = out.concat(CB.gen.problemas.INTERMEDIO);
  return out;
};

/**
 * @param ctx {lucesActuales} — la AMPLIACIÓN nunca se sirve con menos de 3 luces.
 */
CB.gen.problemas.siguienteSubtipo = function (perfil, ctx) {
  ctx = ctx || {};
  let lista = CB.gen.problemas.disponibles(perfil);

  const trimestre = (perfil && perfil.trimestreDeducido) ? perfil.trimestreDeducido : 1;
  if (trimestre >= 3 && (ctx.lucesActuales == null || ctx.lucesActuales >= 3)) {
    lista = lista.concat(CB.gen.problemas.AMPLIACION.filter(function (s) {
      return !ctx.soloNucleares;
    }));
  }
  if (!lista.length) lista = CB.gen.problemas.NUCLEAR.slice();

  let totalPeso = 0, i;
  for (i = 0; i < lista.length; i++) totalPeso += CB.gen.problemas.PESO(lista[i]);

  let servidasTotal = 0;
  for (i = 0; i < lista.length; i++) {
    const pr = (perfil && perfil.problemas) ? perfil.problemas[lista[i]] : null;
    servidasTotal += pr ? (pr.intentos || 0) : 0;
  }

  let mejor = null, mejorDeuda = -Infinity;
  for (i = 0; i < lista.length; i++) {
    const sub = lista[i];
    const peso = CB.gen.problemas.PESO(sub);
    const esperadas = (servidasTotal + 1) * (peso / totalPeso);
    const pr2 = (perfil && perfil.problemas) ? perfil.problemas[sub] : null;
    const servidas = pr2 ? (pr2.intentos || 0) : 0;
    const deuda = peso * (esperadas - servidas);

    if (deuda > mejorDeuda) {
      mejorDeuda = deuda; mejor = sub;
    } else if (deuda === mejorDeuda && mejor) {
      /* Empate: el de menor tiempo medio, para no encadenar los más lentos. */
      const a = (perfil && perfil.problemas && perfil.problemas[mejor]) ? perfil.problemas[mejor].rtMedioMs : 0;
      const b = pr2 ? pr2.rtMedioMs : 0;
      if (b < a) mejor = sub;
    }
  }
  return mejor || 'CAMBIO_1';
};

/* Nivel P1..P20 ↔ subtipo */
CB.gen.problemas.SUBTIPO_DE_NIVEL = {
  P1: 'CAMBIO_1', P2: 'CAMBIO_2', P3: 'COMBINACION_1', P4: 'COMBINACION_2',
  P5: 'COMPARACION_1', P6: 'COMPARACION_2', P7: 'CAMBIO_3', P8: 'CAMBIO_4',
  P9: 'COMPARACION_3', P10: 'COMPARACION_4', P11: 'IGUALACION_1', P12: 'IGUALACION_2',
  P13: 'CAMBIO_5', P14: 'CAMBIO_6', P15: 'COMPARACION_5', P16: 'COMPARACION_6',
  P17: 'IGUALACION_3', P18: 'IGUALACION_4', P19: 'IGUALACION_5', P20: 'IGUALACION_6',
  /* Curso 1.º (3.0.0): las mismas cuatro estructuras nucleares. El curso no
     cambia la plantilla, cambia el techo numérico que la partida pasa en ctx. */
  P21: 'CAMBIO_1', P22: 'CAMBIO_2', P23: 'COMBINACION_1', P24: 'COMBINACION_2',
  /* Cursos 3.º-6.º (3.1.0): las estructuras más duras del banco aditivo, con
     números hasta 999. Los problemas MULTIPLICATIVOS son deuda declarada en
     docs/decisiones.md: exigen plantillas y validación nuevas, no filas. */
  P25: 'IGUALACION_1', P26: 'CAMBIO_5', P27: 'CAMBIO_6', P28: 'COMPARACION_5',
  P29: 'COMPARACION_6',
  P30: 'IGUALACION_3', P31: 'IGUALACION_4', P32: 'COMBINACION_2', P33: 'CAMBIO_5',
  P34: 'COMPARACION_5',
  P35: 'IGUALACION_5', P36: 'IGUALACION_6', P37: 'CAMBIO_6', P38: 'COMPARACION_6',
  P39: 'COMBINACION_1',
  P40: 'IGUALACION_5', P41: 'IGUALACION_6', P42: 'COMPARACION_5', P43: 'CAMBIO_5',
  P44: 'COMBINACION_2'
};

/* Los generadores P1..P20 que consume el catálogo. */
(function () {
  let k;
  for (k in CB.gen.problemas.SUBTIPO_DE_NIVEL) {
    if (!Object.prototype.hasOwnProperty.call(CB.gen.problemas.SUBTIPO_DE_NIVEL, k)) continue;
    (function (nivelId, subtipo) {
      CB.gen.problemas[nivelId] = function (rng, D, ctx) {
        return CB.gen.problemas.generarSubtipo(subtipo, rng, D, ctx);
      };
    })(k, CB.gen.problemas.SUBTIPO_DE_NIVEL[k]);
  }
})();

/* 15-gen-dinero.js — E1…E8 */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.dinero = {};

CB.gen.dinero.MONEDAS  = [1, 2];                   // euros
CB.gen.dinero.BILLETES = [5, 10, 20, 50, 100];     // euros

/* Las que hacen 1 euro justo, que es lo que pregunta la equivalencia de E8. La
   de 1 céntimo no está: cien monedas no es una equivalencia, es una lista. */
CB.gen.dinero.CENTIMOS = [5, 10, 20, 50];          // AMPLIACIÓN, flagAdulto

/* Las CINCO que existen como pieza, que son las cinco que hay en un bolsillo y
   las cinco que tienen fotografía. La de 1 céntimo entra aquí y no arriba porque
   reconocerla sí tiene sentido; multiplicarla por cien, no. */
CB.gen.dinero.PIEZAS_CENTIMO = [1, 5, 10, 20, 50];

/* UNA PIEZA DE CÉNTIMO SE NOMBRA 'c20', NO 20 */
CB.gen.dinero.pieza      = function (c) { return 'c' + c; };
CB.gen.dinero.esCentimo  = function (v) { return typeof v === 'string' && v.charAt(0) === 'c'; };
CB.gen.dinero.valorCent  = function (v) { return parseInt(String(v).slice(1), 10); };

CB.gen.dinero.esMoneda  = function (v) {
  return CB.gen.dinero.esCentimo(v) || CB.gen.dinero.MONEDAS.indexOf(v) !== -1;
};
CB.gen.dinero.esBillete = function (v) { return CB.gen.dinero.BILLETES.indexOf(v) !== -1; };

/* Concordancia obligatoria: «1 euro», no «1 euros». Es material escolar; una
   falta de concordancia en la consigna la ve el maestro a la primera. */
CB.gen.dinero.euros = function (v) {
  return v + (v === 1 ? ' euro' : ' euros');
};

/* SIEMPRE entero + la palabra, NUNCA «0,50 €»: el invariante 3 prohíbe los
   decimales y en 2.º todavía no se han visto. Y la misma concordancia. */
CB.gen.dinero.centimos = function (c) {
  return c + (c === 1 ? ' céntimo' : ' céntimos');
};

CB.gen.dinero.nombre = function (v) {
  if (CB.gen.dinero.esCentimo(v)) {
    return 'la moneda de ' + CB.gen.dinero.centimos(CB.gen.dinero.valorCent(v));
  }
  if (CB.gen.dinero.esMoneda(v))  return 'la moneda de ' + CB.gen.dinero.euros(v);
  if (CB.gen.dinero.esBillete(v)) return 'el billete de ' + CB.gen.dinero.euros(v);
  return CB.gen.dinero.euros(v);
};

/* Reparte un importe en piezas reales, de mayor a menor. */
CB.gen.dinero.descomponer = function (importe, conBilletes) {
  const piezas = [];
  let resto = importe, i;
  const valores = conBilletes
    ? CB.gen.dinero.BILLETES.slice().reverse().concat(CB.gen.dinero.MONEDAS.slice().reverse())
    : CB.gen.dinero.MONEDAS.slice().reverse();
  for (i = 0; i < valores.length; i++) {
    while (resto >= valores[i] && piezas.length < 12) {
      piezas.push(valores[i]);
      resto -= valores[i];
    }
  }
  return piezas;
};

/* E1 Reconocer monedas y billetes */
CB.gen.dinero.E1 = function (rng, D) {
  const todos = CB.gen.dinero.MONEDAS.concat(CB.gen.dinero.BILLETES);
  const v = CB.util.elegir(rng, todos);
  return {
    formato: 'opciones4',
    consigna: 'Toca ' + CB.gen.dinero.nombre(v) + '.',

    piezasDinero: true,
    respuesta: v,
    expr: 'reconocer' + v,
    diagnostico: false,
    contexto: { pieza: v, esMoneda: CB.gen.dinero.esMoneda(v) },
    distractoresFijos: CB.util.barajar(
      todos.filter(function (x) { return x !== v; }), rng
    ).slice(0, 3)
  };
};

/* E2 Contar con monedas de 1 y 2 € */
CB.gen.dinero.E2 = function (rng, D) {
  const n = CB.util.ent(rng, 3, (D === 1) ? 5 : 8), piezas = [];
  let total = 0, i, v;
  for (i = 0; i < n; i++) {
    v = CB.util.elegir(rng, CB.gen.dinero.MONEDAS);
    piezas.push(v); total += v;
  }
  return {
    formato: 'monedas',
    consigna: '¿Cuántos euros hay en total?',
    piezas: piezas,
    respuesta: total,
    expr: 'contarM' + piezas.join('_'),
    diagnostico: true,
    contexto: { soloMonedas: true }
  };
};

/* E3 Contar con billetes */
CB.gen.dinero.E3 = function (rng, D) {
  const n = CB.util.ent(rng, 2, (D === 1) ? 3 : 4);
  let piezas = [], total = 0, i, v;
  const pool = (D === 3) ? CB.gen.dinero.BILLETES : [5, 10, 20];
  for (i = 0; i < n; i++) {
    v = CB.util.elegir(rng, pool);
    if (total + v > 100) break;
    piezas.push(v); total += v;
  }
  if (!piezas.length) { piezas = [5]; total = 5; }
  return {
    formato: 'monedas',
    consigna: '¿Cuántos euros hay en billetes?',
    piezas: piezas,
    respuesta: total,
    expr: 'contarB' + piezas.join('_'),
    diagnostico: true,
    contexto: { soloBilletes: true }
  };
};

/* E4 Equivalencias entre billetes */
CB.gen.dinero.E4 = function (rng, D) {
  const grande = CB.util.elegir(rng, [10, 20, 50, 100]);
  let pequeno = CB.util.elegir(rng, CB.gen.dinero.BILLETES.filter(function (v) {
    return v < grande && grande % v === 0;
  }));
  if (pequeno == null) pequeno = 5;
  return {
    formato: 'opciones4',
    consigna: '¿Cuántos billetes de ' + CB.gen.dinero.euros(pequeno) +
              ' hacen falta para ' + CB.gen.dinero.euros(grande) + '?',
    respuesta: grande / pequeno,
    expr: 'equiv' + grande + '_' + pequeno,
    diagnostico: true
  };
};

/* E5 Pagar con importe exacto */
CB.gen.dinero.E5 = function (rng, D) {
  const precio = CB.util.ent(rng, 3, (D === 1) ? 12 : 50);
  return {
    formato: 'monedas',
    consigna: 'Paga justo ' + CB.gen.dinero.euros(precio) + '.',
    modo: 'pagar',
    objetivo: precio,
    disponibles: CB.gen.dinero.MONEDAS.concat([5, 10, 20]),
    respuesta: precio,
    expr: 'pagar' + precio,
    diagnostico: true
  };
};

/* E6 El cambio */
CB.gen.dinero.E6 = function (rng, D) {
  const precio = CB.util.ent(rng, 2, (D === 1) ? 8 : 18);
  let pagaCon = CB.util.elegir(rng, CB.gen.dinero.BILLETES.filter(function (v) {
    return v > precio && v <= 20;
  }));
  if (pagaCon == null) pagaCon = 20;
  return {
    formato: 'teclado',
    consigna: 'El precio es ' + CB.gen.dinero.euros(precio) + '. Pagas con ' +
              CB.gen.dinero.euros(pagaCon) + '. ¿Cuánto te devuelven?',
    operacion: '-', operandos: [pagaCon, precio],
    respuesta: pagaCon - precio,
    expr: 'cambio' + pagaCon + '_' + precio,
    diagnostico: true
  };
};

/* E7 La compra: gasto total */
CB.gen.dinero.E7 = function (rng, D) {
  const a = CB.util.ent(rng, 2, (D === 1) ? 15 : 45);
  let b = CB.util.ent(rng, 2, (D === 1) ? 15 : 45);
  if (a + b > 99) b = 99 - a;
  return {
    formato: 'teclado',
    consigna: 'Una cosa cuesta ' + CB.gen.dinero.euros(a) + ' y la otra ' +
              CB.gen.dinero.euros(b) + '. ¿Cuánto es en total?',
    operacion: '+', operandos: [a, b],
    respuesta: a + b,
    expr: 'compra' + a + '_' + b,
    diagnostico: true
  };
};

/* E8 Céntimos — AMPLIACIÓN, apagada por defecto */
CB.gen.dinero.E8 = function (rng, D) {
  if (D === 1 || CB.util.ent(rng, 1, 2) === 1) return CB.gen.dinero.E8reconocer(rng, D);
  return CB.gen.dinero.E8equivalencia(rng, D);
};

CB.gen.dinero.E8reconocer = function (rng, D) {
  const todas = CB.gen.dinero.PIEZAS_CENTIMO.map(CB.gen.dinero.pieza);
  const v = CB.util.elegir(rng, todas);
  return {
    formato: 'opciones4',
    consigna: 'Toca ' + CB.gen.dinero.nombre(v) + '.',
    piezasDinero: true,
    /* NO ES UN NÚMERO, y es a propósito: ver la cabecera del fichero. */
    respuesta: v,
    expr: 'reconocerC' + v,
    diagnostico: false,
    contexto: { pieza: v, esMoneda: true, esCentimo: true },
    distractoresFijos: CB.util.barajar(
      todas.filter(function (x) { return x !== v; }), rng
    ).slice(0, 3)
  };
};

CB.gen.dinero.E8equivalencia = function (rng, D) {
  const c = CB.util.elegir(rng, CB.gen.dinero.CENTIMOS);
  const cuantas = Math.round(100 / c);
  return {
    formato: 'opciones4',
    /* SIEMPRE entero + la palabra «céntimos». Nunca «0,50 €». */
    consigna: '¿Cuántas monedas de ' + CB.gen.dinero.centimos(c) + ' hacen 1 euro?',
    respuesta: cuantas,
    expr: 'cent' + c,
    diagnostico: false
  };
};

/* ——— Curso 1.º (3.0.0): E9…E10 ——— */

/* E9 Contar monedas de 1 y 2 € hasta 10 € */
CB.gen.dinero.E9 = function (rng, D) {
  const n = CB.util.ent(rng, 2, (D === 1) ? 4 : 6);
  const piezas = [];
  let total = 0, i, v;
  for (i = 0; i < n; i++) {
    v = CB.util.elegir(rng, CB.gen.dinero.MONEDAS);
    if (total + v > 10) break;
    piezas.push(v); total += v;
  }
  if (!piezas.length) { piezas.push(1); total = 1; }
  return {
    formato: 'monedas',
    consigna: '¿Cuántos euros hay en total?',
    piezas: piezas,
    respuesta: total,
    expr: 'contarP' + piezas.join('_'),
    diagnostico: true,
    contexto: { soloMonedas: true }
  };
};

/* E10 Pagar justo hasta 20 € */
CB.gen.dinero.E10 = function (rng, D) {
  const precio = CB.util.ent(rng, 2, (D === 1) ? 9 : 20);
  return {
    formato: 'monedas',
    consigna: 'Paga justo ' + CB.gen.dinero.euros(precio) + '.',
    modo: 'pagar',
    objetivo: precio,
    disponibles: CB.gen.dinero.MONEDAS.concat([5, 10]),
    respuesta: precio,
    expr: 'pagarP' + precio,
    diagnostico: true
  };
};

/* ——— Cursos 3.º-4.º (3.1.0): E11…E14 ——— */

/* E11 Céntimos: contar y equivaler (3.º). SIEMPRE céntimos enteros. */
CB.gen.dinero.E11 = function (rng, D) {
  if (rng() < 0.5) {
    const c = CB.util.elegir(rng, CB.gen.dinero.CENTIMOS);
    return {
      formato: 'opciones4',
      consigna: '¿Cuántas monedas de ' + CB.gen.dinero.centimos(c) + ' hacen 1 euro?',
      respuesta: 100 / c,
      expr: 'e11eq' + c,
      diagnostico: false
    };
  }
  const c2 = CB.util.elegir(rng, CB.gen.dinero.CENTIMOS);
  const n = CB.util.ent(rng, 2, (D === 1) ? 4 : 6);
  return {
    formato: 'teclado',
    consigna: '¿Cuántos céntimos son ' + n + ' monedas de ' +
              CB.gen.dinero.centimos(c2) + '?',
    operacion: '×', operandos: [n, c2],
    respuesta: n * c2,
    expr: 'e11c' + n + '_' + c2,
    diagnostico: true,
    tablasCompletas: true
  };
};

/* E12 La compra grande (3.º) */
CB.gen.dinero.E12 = function (rng, D) {
  if (rng() < 0.5) {
    const a = CB.util.ent(rng, 25, (D === 1) ? 200 : 499);
    const b = CB.util.ent(rng, 25, Math.min(499, 999 - a));
    return {
      formato: 'teclado',
      consigna: 'Una bici cuesta ' + a + ' € y un casco ' + b +
                ' €. ¿Cuánto es en total?',
      operacion: '+', operandos: [a, b],
      respuesta: a + b,
      expr: 'e12s' + a + '_' + b,
      diagnostico: true
    };
  }
  const precio = CB.util.ent(rng, 12, 89);
  return {
    formato: 'teclado',
    consigna: 'Cuesta ' + precio + ' €. Pagas con 100 €. ¿Cuánto te devuelven?',
    operacion: '-', operandos: [100, precio],
    respuesta: 100 - precio,
    expr: 'e12c' + precio,
    diagnostico: true
  };
};

/* E13 El cambio con céntimos (4.º): la respuesta lleva coma */
CB.gen.dinero.E13 = function (rng, D) {
  const precio = CB.util.ent(rng, 5, 19) * 25;             // 1,25 … 4,75
  const paga = 500;
  return {
    formato: 'teclado', conComa: true,
    consigna: 'Cuesta ' + CB.gen.motor.coma(precio, 100) +
              ' €. Pagas con 5 €. ¿Cuánto te devuelven?',
    respuesta: CB.gen.motor.dec(paga - precio, 100),
    expr: 'e13_' + precio,
    diagnostico: false
  };
};

/* E14 El presupuesto (4.º) */
CB.gen.dinero.E14 = function (rng, D) {
  const total = CB.util.elegir(rng, [200, 300, 500]);
  const a = CB.util.ent(rng, 40, Math.floor(total / 2) - 10);
  const b = CB.util.ent(rng, 40, total - a - 10);
  return {
    formato: 'teclado',
    consigna: 'Tienes ' + total + ' €. Compras por ' + a + ' € y por ' + b +
              ' €. ¿Cuánto te queda?',
    respuesta: total - a - b,
    expr: 'e14_' + total + '_' + a + '_' + b,
    diagnostico: false
  };
};

/* 16-gen-vocabulario.js — V1…V8 (Diccionario de Bloques) */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.vocabulario = {};

CB.gen.vocabulario.terminosDe = function (nivelId) {
  return CB.datos.GLOSARIO.filter(function (g) { return g.n === nivelId; });
};

/* Un ítem de vocabulario es: se da la definición, se elige el término.
   El índice del término dentro del glosario hace de «respuesta» entera, para
   cumplir el invariante 5 sin inventar un número que no significa nada. */
function itemVocab(nivelId, rng, D) {
  let propios = CB.gen.vocabulario.terminosDe(nivelId);
  if (!propios.length) propios = CB.datos.GLOSARIO.slice(0, 6);

  const elegido = CB.util.elegir(rng, propios);
  const iGlobal = CB.datos.GLOSARIO.indexOf(elegido);

  /* Los distractores salen del MISMO nivel siempre que se pueda: confundir
     «sumando» con «decena» no informa de nada; confundirlo con «total» sí. */
  let candidatos = propios.filter(function (g) { return g.t !== elegido.t; });
  if (candidatos.length < 3) {
    candidatos = candidatos.concat(
      CB.datos.GLOSARIO.filter(function (g) {
        return g.t !== elegido.t && candidatos.indexOf(g) === -1;
      })
    );
  }
  const distractores = CB.util.barajar(candidatos, rng).slice(0, 3);

  return {
    formato: 'opciones4',
    consigna: elegido.d,
    preguntaPrevia: '¿Qué palabra es?',
    respuesta: iGlobal,
    /* La UI pinta textos, no números: opcionesTexto lleva las palabras. */
    opcionesTexto: null,
    termino: elegido.t,
    esMayores: !!elegido.mayores,
    distractoresTexto: distractores.map(function (g) { return g.t; }),
    distractoresIndice: distractores.map(function (g) { return CB.datos.GLOSARIO.indexOf(g); }),
    expr: 'voc_' + elegido.t.replace(/\s+/g, '-'),
    diagnostico: false,
    esTextual: true
  };
}

CB.gen.vocabulario.V1 = function (rng, D) { return itemVocab('V1', rng, D); };
CB.gen.vocabulario.V2 = function (rng, D) { return itemVocab('V2', rng, D); };
CB.gen.vocabulario.V3 = function (rng, D) { return itemVocab('V3', rng, D); };
CB.gen.vocabulario.V6 = function (rng, D) { return itemVocab('V6', rng, D); };
CB.gen.vocabulario.V7 = function (rng, D) { return itemVocab('V7', rng, D); };
CB.gen.vocabulario.V8 = function (rng, D) { return itemVocab('V8', rng, D); };

/* V4 Comparar: se responde en la balanza, no eligiendo palabra */
CB.gen.vocabulario.V4 = function (rng, D) {
  const a = CB.util.ent(rng, 1, (D === 1) ? 20 : 99);
  const b = CB.util.ent(rng, 1, (D === 1) ? 20 : 99);
  const signo = (a > b) ? '>' : (a < b ? '<' : '=');
  const palabra = (signo === '>') ? 'mayor que' : (signo === '<' ? 'menor que' : 'igual');
  return {
    formato: 'balanza',
    consigna: '¿' + a + ' es mayor, menor o igual que ' + b + '?',
    visual: { tipo: 'balanza', a: a, b: b },
    opcionesFijas: ['>', '<', '='],
    respuestaSigno: signo,
    respuesta: Math.max(a, b),
    termino: palabra,
    expr: 'voccomp' + a + signo + b,
    diagnostico: false,
    esTextual: false
  };
};

/* V5 Orden y posición: se responde ordenando */
CB.gen.vocabulario.V5 = function (rng, D) {
  const inicio = CB.util.ent(rng, 1, 14);
  const cuantos = (D === 1) ? 3 : 4;
  const orden = [];
  let i;
  for (i = 0; i < cuantos; i++) orden.push(inicio + i);
  return {
    formato: 'ordenar',
    consigna: 'Coloca las vagonetas de la primera a la última.',
    orden: orden,
    piezas: CB.util.barajar(orden, rng),
    respuesta: orden[orden.length - 1],
    termino: 'primero',
    expr: 'vocord' + inicio + '_' + cuantos,
    diagnostico: false,
    esTextual: false
  };
};

/* Términos que el niño «desbloquea» al acertar: alimentan el logro
   «Palabra de piedra» y la pantalla del Diccionario. */
CB.gen.vocabulario.terminoDe = function (item) {
  return item && item.termino ? item.termino : null;
};

/* 19-gen-motor.js — Ayudas compartidas por los generadores de 3.º-6.º (3.1.0).
   PURO: sin DOM y sin Math.random; todo rng viene inyectado. Los decimales se
   construyen SIEMPRE como entero escalado dividido UNA vez entre 10 o 100:
   así parseFloat(lo tecleado) y la respuesta son el mismo doble exacto. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.motor = {};

/* Un número grande, legible: 45 231 (espacio, nunca punto: el guardián de los
   decimales busca [,.] pegado a cifra, y el punto de millar lo pisaría). */
CB.gen.motor.sep = function (n) {
  const s = String(Math.round(Math.abs(n)));
  let out = '', i;
  for (i = 0; i < s.length; i++) {
    if (i > 0 && (s.length - i) % 3 === 0) out += ' ';
    out += s.charAt(i);
  }
  return (n < 0 ? '−' : '') + out;
};

/* Entero escalado → texto con coma: coma(345, 100) = '3,45'. */
CB.gen.motor.coma = function (escalado, escala) {
  const neg = escalado < 0 ? '−' : '';
  const abs = Math.abs(escalado);
  const ent = Math.floor(abs / escala);
  let dec = String(abs % escala);
  while (dec.length < String(escala).length - 1) dec = '0' + dec;
  dec = dec.replace(/0+$/, '');
  return neg + ent + (dec.length ? ',' + dec : '');
};

/* Entero escalado → Number exacto: dec(345, 100) = 3.45. UNA división. */
CB.gen.motor.dec = function (escalado, escala) { return escalado / escala; };

CB.gen.motor.mcd = function (a, b) {
  a = Math.abs(a); b = Math.abs(b);
  while (b) { const t = a % b; a = b; b = t; }
  return a || 1;
};

CB.gen.motor.mcm = function (a, b) {
  return (a * b) / CB.gen.motor.mcd(a, b);
};

/* La fracción como texto: es la RESPUESTA de los ítems de fracción (una
   cadena, como 'c20' en el dinero: el motor de distractores hace aritmética
   y una fracción no es un número tecleable). */
CB.gen.motor.fstr = function (num, den) { return num + '/' + den; };

/* Recorre [min, max] según D, igual que tramo() en 10-gen-numeracion. */
CB.gen.motor.tramo = function (min, max, D, rng) {
  return CB.gen.numeracion._tramo(min, max, D, rng);
};

/* 19a-gen-division.js — D1…D17 (cursos 3.º-6.º) */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.division = {};

/* a ÷ d = c (resto r). Se construye desde el cociente: la división siempre
   cuadra por construcción, nunca por reintento. */
function itemDiv(a, d, c, pideResto, r) {
  return {
    formato: 'teclado',
    operacion: '÷',
    operandos: [a, d],
    respuesta: pideResto ? r : c,
    expr: a + '/' + d + (pideResto ? 'r' : ''),
    consigna: pideResto
      ? (a + ' ÷ ' + d + ' — ¿cuánto SOBRA?')
      : (a + ' ÷ ' + d),
    diagnostico: true,
    contexto: { cociente: c, resto: r || 0 }
  };
}
CB.gen.division._itemDiv = itemDiv;

/* D1 Repartir en partes iguales (3.º) */
CB.gen.division.D1 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 5);
  const c = CB.util.ent(rng, 2, (D === 1) ? 5 : 10);
  const a = d * c;
  return {
    formato: 'opciones4',
    consigna: a + ' caramelos entre ' + d + ' amigos. ¿Cuántos a cada uno?',
    operacion: '÷', operandos: [a, d],
    respuesta: c,
    expr: 'rep' + a + '_' + d,
    diagnostico: true
  };
};

/* D2 Dividir con las tablas del 2, del 5 y del 10 (3.º) */
CB.gen.division.D2 = function (rng, D) {
  const d = CB.util.elegir(rng, [2, 5, 10]);
  const c = CB.util.ent(rng, 1, (D === 1) ? 5 : 10);
  return itemDiv(d * c, d, c, false, 0);
};

/* D3 Dividir con todas las tablas (3.º) */
CB.gen.division.D3 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 10);
  const c = CB.util.ent(rng, 2, (D === 1) ? 5 : 10);
  return itemDiv(d * c, d, c, false, 0);
};

/* D4 La división con resto (3.º): pide el cociente o lo que sobra */
CB.gen.division.D4 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 9);
  const c = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  const r = CB.util.ent(rng, 1, d - 1);
  return itemDiv(d * c + r, d, c, rng() < 0.4, r);
};

/* D5 Dividir dos cifras entre una, exacta (3.º) */
CB.gen.division.D5 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 9);
  const c = CB.util.ent(rng, Math.ceil(10 / d) + 1, Math.floor(99 / d));
  return itemDiv(d * c, d, c, false, 0);
};

/* D6 La prueba de la división (3.º): divisor × cociente + resto */
CB.gen.division.D6 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 9);
  const c = CB.util.ent(rng, 3, (D === 1) ? 10 : 30);
  const r = CB.util.ent(rng, 0, d - 1);
  return {
    formato: 'teclado',
    consigna: 'El divisor es ' + d + ', el cociente ' + c + ' y el resto ' + r +
              '. ¿Qué número se dividió?',
    respuesta: d * c + r,
    expr: 'prueba' + d + '_' + c + '_' + r,
    diagnostico: false
  };
};

/* D7 Tres cifras entre una, exacta (4.º) */
CB.gen.division.D7 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 9);
  const c = CB.util.ent(rng, Math.ceil(100 / d) + 1, Math.floor(999 / d));
  return itemDiv(d * c, d, c, false, 0);
};

/* D8 Con resto y números grandes (4.º) */
CB.gen.division.D8 = function (rng, D) {
  const d = CB.util.ent(rng, 3, 9);
  const c = CB.util.ent(rng, 12, (D === 1) ? 40 : 99);
  const r = CB.util.ent(rng, 1, d - 1);
  return itemDiv(d * c + r, d, c, rng() < 0.4, r);
};

/* D9 Dividir entre 10, 100 y 1.000 (4.º) */
CB.gen.division.D9 = function (rng, D) {
  const pot = CB.util.elegir(rng, (D === 1) ? [10, 100] : [10, 100, 1000]);
  const c = CB.util.ent(rng, 2, 99);
  return itemDiv(c * pot, pot, c, false, 0);
};

/* D10 Entre dos cifras: iniciación (4.º) */
CB.gen.division.D10 = function (rng, D) {
  const d = CB.util.elegir(rng, [11, 12, 15, 20, 25]);
  const c = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  return itemDiv(d * c, d, c, false, 0);
};

/* D11 La mitad, el tercio y el cuarto (4.º) */
CB.gen.division.D11 = function (rng, D) {
  const par = CB.util.elegir(rng, [[2, 'la mitad'], [3, 'el tercio'], [4, 'el cuarto']]);
  const c = CB.util.ent(rng, 25, (D === 1) ? 200 : 2400);
  const a = c * par[0];
  return {
    formato: 'teclado',
    consigna: '¿Cuánto es ' + par[1] + ' de ' + CB.gen.motor.sep(a) + '?',
    operacion: '÷', operandos: [a, par[0]],
    respuesta: c,
    expr: 'parte' + par[0] + '_' + a,
    diagnostico: true
  };
};

/* D12 Entre dos cifras (5.º) */
CB.gen.division.D12 = function (rng, D) {
  const d = CB.util.ent(rng, 11, 30);
  const c = CB.util.ent(rng, 3, (D === 1) ? 12 : 40);
  return itemDiv(d * c, d, c, false, 0);
};

/* D13 Exacta y entera (5.º): con dos cifras y resto */
CB.gen.division.D13 = function (rng, D) {
  const d = CB.util.ent(rng, 11, 25);
  const c = CB.util.ent(rng, 4, (D === 1) ? 15 : 60);
  const r = CB.util.ent(rng, 0, d - 1);
  return itemDiv(d * c + r, d, c, r > 0 && rng() < 0.4, r);
};

/* D14 Números grandes (5.º) */
CB.gen.division.D14 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 12);
  const c = CB.util.ent(rng, 300, (D === 1) ? 2000 : 8000);
  return itemDiv(d * c, d, c, false, 0);
};

/* D15 Cocientes con ceros (5.º): 2.412 ÷ 12 = 201 */
CB.gen.division.D15 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 12);
  const c = CB.util.ent(rng, 1, 9) * 100 + CB.util.ent(rng, 1, 9);
  return itemDiv(d * c, d, c, false, 0);
};

/* D16 Divisores grandes (6.º) */
CB.gen.division.D16 = function (rng, D) {
  const d = CB.util.ent(rng, 25, 99);
  const c = CB.util.ent(rng, 10, (D === 1) ? 40 : 99);
  return itemDiv(d * c, d, c, false, 0);
};

/* D17 Estimar el cociente (6.º) */
CB.gen.division.D17 = function (rng, D) {
  const d = CB.util.ent(rng, 3, 9);
  const cRedondo = CB.util.ent(rng, 2, 9) * 100;
  const a = cRedondo * d + CB.util.ent(rng, 1, d * 9);
  return {
    formato: 'opciones4',
    consigna: '¿Cuál es la MEJOR estimación de ' + CB.gen.motor.sep(a) + ' ÷ ' + d + '?',
    respuesta: cRedondo,
    expr: 'est' + a + '_' + d,
    diagnostico: false,
    distractoresFijos: [cRedondo / 10, cRedondo * 10, cRedondo + 500]
  };
};

/* 19b-gen-fracciones.js — F1…F20 (cursos 3.º-6.º).
   LA RESPUESTA DE UNA FRACCIÓN ES UNA CADENA ('3/4'), como 'c20' en el
   dinero: no se puede teclear y el motor de distractores haría aritmética con
   ella. Todos los ítems de fracción-como-respuesta llevan respuestaFraccion,
   opciones4 y distractoresFijos; los de resultado entero o decimal, teclado. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.fracciones = {};

const fstr = function (n, d) { return CB.gen.motor.fstr(n, d); };

function itemFrac(consigna, num, den, fijos, expr, visual) {
  const resp = fstr(num, den);
  /* Los fijos se DEDUPLICAN aquí, no en cada nivel: den−num puede coincidir
     con num±1, a·b con a+b+1… y un juego de opciones con dos iguales rompe el
     invariante 5. Si tras depurar faltan, se rellena con fracciones vecinas. */
  const unicos = [];
  fijos.forEach(function (f) {
    if (f !== resp && unicos.indexOf(f) === -1) unicos.push(f);
  });
  let k = 2;
  while (unicos.length < 3 && k < 40) {
    const cand = fstr(num + k, den + k + 1);
    if (cand !== resp && unicos.indexOf(cand) === -1) unicos.push(cand);
    k++;
  }
  const it = {
    formato: 'opciones4',
    consigna: consigna,
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: unicos.slice(0, 3),
    expr: expr,
    diagnostico: false
  };
  if (visual) it.visual = visual;
  return it;
}
CB.gen.fracciones._itemFrac = itemFrac;

/* F1 Mitades, tercios y cuartos (3.º) */
CB.gen.fracciones.F1 = function (rng, D) {
  const den = CB.util.elegir(rng, (D === 1) ? [2, 4] : [2, 3, 4]);
  return itemFrac('¿Qué parte está pintada?', 1, den,
    [2, 3, 4, 6].filter(function (x) { return x !== den; })
      .slice(0, 3).map(function (x) { return fstr(1, x); }),
    'f1_' + den, { tipo: 'fraccion', partes: den, sombreadas: 1 });
};

/* F2 ¿Qué fracción está pintada? (3.º) */
CB.gen.fracciones.F2 = function (rng, D) {
  const den = CB.util.elegir(rng, (D === 1) ? [4, 5, 6] : [5, 6, 8, 10, 12]);
  const num = CB.util.ent(rng, 2, den - 1);
  const fijos = [];
  if (num - 1 >= 1) fijos.push(fstr(num - 1, den));
  if (num + 1 <= den) fijos.push(fstr(num + 1, den));
  fijos.push(fstr(den - num, den));
  if (fijos.length < 3) fijos.push(fstr(num, den + 2));
  return itemFrac('¿Qué fracción está pintada?', num, den,
    fijos.slice(0, 3), 'f2_' + num + '_' + den,
    { tipo: 'fraccion', partes: den, sombreadas: num });
};

/* F3 La fracción de una cantidad (3.º) */
CB.gen.fracciones.F3 = function (rng, D) {
  const den = CB.util.elegir(rng, [2, 3, 4, 5]);
  const parte = CB.util.ent(rng, 2, (D === 1) ? 10 : 20);
  const total = den * parte;
  return {
    formato: 'teclado',
    consigna: '¿Cuánto es ' + fstr(1, den) + ' de ' + total + '?',
    operacion: '÷', operandos: [total, den],
    respuesta: parte,
    expr: 'f3_' + den + '_' + total,
    diagnostico: true
  };
};

/* F4 Comparar fracciones sencillas (3.º): la mayor de las unitarias */
CB.gen.fracciones.F4 = function (rng, D) {
  const pool = CB.util.barajar([2, 3, 4, 5, 6, 8, 10, 12], rng).slice(0, 4);
  pool.sort(function (a, b) { return a - b; });
  return itemFrac('Toca la fracción MAYOR.', 1, pool[0],
    pool.slice(1).map(function (x) { return fstr(1, x); }),
    'f4_' + pool.join('_'));
};

/* F5 Fracciones equivalentes (4.º) */
CB.gen.fracciones.F5 = function (rng, D) {
  const base = CB.util.elegir(rng, [[1, 2], [1, 3], [2, 3], [1, 4], [3, 4], [2, 5]]);
  const k = CB.util.ent(rng, 2, (D === 1) ? 3 : 4);
  return itemFrac('¿Cuál vale lo MISMO que ' + fstr(base[0], base[1]) + '?',
    base[0] * k, base[1] * k,
    [fstr(base[0], base[1] * k), fstr(base[0] + 1, base[1]),
     fstr(base[0] * k, base[1] * k + 1)],
    'f5_' + base.join('_') + 'x' + k);
};

/* F6 La fracción de una cantidad grande (4.º) */
CB.gen.fracciones.F6 = function (rng, D) {
  const den = CB.util.elegir(rng, [2, 3, 4, 5, 10]);
  const num = CB.util.ent(rng, 1, den - 1);
  const parte = CB.util.ent(rng, 5, (D === 1) ? 30 : 90);
  const total = den * parte;
  return {
    formato: 'teclado',
    consigna: '¿Cuánto es ' + fstr(num, den) + ' de ' + CB.gen.motor.sep(total) + '?',
    respuesta: num * parte,
    expr: 'f6_' + num + '_' + den + '_' + total,
    diagnostico: false
  };
};

/* F7 Mayor que un entero (4.º) */
CB.gen.fracciones.F7 = function (rng, D) {
  const den = CB.util.elegir(rng, [2, 3, 4, 5]);
  const num = den + CB.util.ent(rng, 1, den);
  return itemFrac('Toca la fracción MAYOR que un entero.', num, den,
    [fstr(Math.max(1, den - 1), den), fstr(1, den), fstr(den, den + 1)],
    'f7_' + num + '_' + den);
};

/* F8 Sumar con el mismo denominador (4.º) */
CB.gen.fracciones.F8 = function (rng, D) {
  const den = CB.util.elegir(rng, [5, 6, 8, 10, 12]);
  const a = CB.util.ent(rng, 1, den - 3);
  const b = CB.util.ent(rng, 1, den - a - 1);
  return itemFrac(fstr(a, den) + ' + ' + fstr(b, den),
    a + b, den,
    [fstr(a + b, den * 2), fstr(a * b, den), fstr(a + b + 1, den)],
    'f8_' + a + '_' + b + '_' + den);
};

/* F9 La fracción y el decimal (4.º) */
CB.gen.fracciones.F9 = function (rng, D) {
  const par = CB.util.elegir(rng, [
    [['0,5'], 1, 2, [[1, 5], [2, 5], [1, 4]]],
    [['0,25'], 1, 4, [[1, 2], [2, 5], [1, 5]]],
    [['0,75'], 3, 4, [[7, 5], [1, 4], [3, 5]]],
    [['0,1'], 1, 10, [[1, 2], [1, 5], [10, 1]]]
  ]);
  return itemFrac('¿Qué fracción es ' + par[0][0] + '?', par[1], par[2],
    par[3].map(function (p) { return fstr(p[0], p[1]); }),
    'f9_' + par[0][0]);
};

/* F10 Simplificar (5.º) */
CB.gen.fracciones.F10 = function (rng, D) {
  const base = CB.util.elegir(rng, [[1, 2], [1, 3], [2, 3], [1, 4], [3, 4], [2, 5], [1, 5]]);
  const k = CB.util.ent(rng, 2, (D === 1) ? 3 : 5);
  return itemFrac('Simplifica ' + fstr(base[0] * k, base[1] * k) + '.',
    base[0], base[1],
    [fstr(base[0], base[1] * k), fstr(base[0] + 1, base[1] + 1),
     fstr(base[0] * k, base[1])],
    'f10_' + base.join('_') + 'x' + k);
};

/* F11 El denominador común (5.º) */
CB.gen.fracciones.F11 = function (rng, D) {
  const pares = [[2, 3], [3, 4], [2, 5], [4, 6], [3, 5], [4, 10], [6, 8], [2, 7]];
  const p = CB.util.elegir(rng, (D === 1) ? pares.slice(0, 4) : pares);
  return {
    formato: 'teclado',
    consigna: 'Para sumar ' + fstr(1, p[0]) + ' y ' + fstr(1, p[1]) +
              ', ¿qué denominador común usas? (el menor)',
    respuesta: CB.gen.motor.mcm(p[0], p[1]),
    expr: 'f11_' + p.join('_'),
    diagnostico: false
  };
};

/* F12 Sumar y restar con el mismo denominador (5.º) */
CB.gen.fracciones.F12 = function (rng, D) {
  const den = CB.util.elegir(rng, [6, 8, 9, 10, 12]);
  const resta = rng() < 0.5;
  const a = CB.util.ent(rng, 3, den - 1);
  const b = CB.util.ent(rng, 1, a - 1);
  const sumaReal = resta ? (a - b) : (a + b);
  return itemFrac(fstr(a, den) + (resta ? ' − ' : ' + ') + fstr(b, den),
    sumaReal, den,
    [fstr(sumaReal, resta ? den : den * 2), fstr(Math.abs(a * 1 - b) + 1, den),
     fstr(sumaReal + 1, den)],
    'f12_' + a + (resta ? 'm' : 'p') + b + '_' + den);
};

/* F13 La fracción de una cantidad (5.º) */
CB.gen.fracciones.F13 = function (rng, D) {
  const den = CB.util.elegir(rng, [3, 4, 5, 6, 8, 10]);
  const num = CB.util.ent(rng, 1, den - 1);
  const parte = CB.util.ent(rng, 10, (D === 1) ? 50 : 120);
  return {
    formato: 'teclado',
    consigna: '¿Cuánto es ' + fstr(num, den) + ' de ' + CB.gen.motor.sep(den * parte) + '?',
    respuesta: num * parte,
    expr: 'f13_' + num + '_' + den + '_' + parte,
    diagnostico: false
  };
};

/* F14 El número mixto (5.º) */
CB.gen.fracciones.F14 = function (rng, D) {
  const den = CB.util.elegir(rng, [2, 3, 4, 5]);
  const ent = CB.util.ent(rng, 1, 3);
  const resto = CB.util.ent(rng, 1, den - 1);
  const num = ent * den + resto;
  return {
    formato: 'teclado',
    consigna: fstr(num, den) + ' son ' + ent +
              (ent === 1 ? ' entero' : ' enteros') + ' y ¿cuántos ' +
              ['medios', 'tercios', 'cuartos', 'quintos'][den - 2] + '?',
    respuesta: resto,
    expr: 'f14_' + num + '_' + den,
    diagnostico: false
  };
};

/* F15 De la fracción al decimal (5.º) */
CB.gen.fracciones.F15 = function (rng, D) {
  const par = CB.util.elegir(rng, [[1, 2, 5, 10], [1, 4, 25, 100], [3, 4, 75, 100],
                                   [1, 5, 2, 10], [3, 10, 3, 10], [7, 10, 7, 10],
                                   [1, 10, 1, 10], [9, 10, 9, 10]]);
  return {
    formato: 'teclado',
    conComa: true,
    consigna: 'Escribe ' + fstr(par[0], par[1]) + ' como número con coma.',
    respuesta: CB.gen.motor.dec(par[2], par[3]),
    expr: 'f15_' + par[0] + '_' + par[1],
    diagnostico: false
  };
};

/* F16 Sumar con distinto denominador (6.º) */
CB.gen.fracciones.F16 = function (rng, D) {
  const casos = [[1, 2, 1, 4, 3, 4], [1, 2, 1, 6, 4, 6], [1, 3, 1, 6, 3, 6],
                 [1, 2, 1, 8, 5, 8], [1, 4, 1, 8, 3, 8], [1, 2, 3, 10, 8, 10],
                 [1, 3, 1, 9, 4, 9], [1, 5, 3, 10, 5, 10]];
  const c = CB.util.elegir(rng, casos);
  return itemFrac(fstr(c[0], c[1]) + ' + ' + fstr(c[2], c[3]),
    c[4], c[5],
    [fstr(c[0] + c[2], c[1] + c[3]), fstr(c[4] + 1, c[5]), fstr(c[4], c[5] * 2)],
    'f16_' + c.slice(0, 4).join('_'));
};

/* F17 Restar con distinto denominador (6.º) */
CB.gen.fracciones.F17 = function (rng, D) {
  const casos = [[1, 2, 1, 4, 1, 4], [1, 2, 1, 6, 2, 6], [1, 3, 1, 6, 1, 6],
                 [3, 4, 1, 2, 1, 4], [1, 2, 1, 8, 3, 8], [7, 10, 1, 2, 2, 10],
                 [2, 3, 1, 6, 3, 6], [1, 2, 1, 10, 4, 10]];
  const c = CB.util.elegir(rng, casos);
  return itemFrac(fstr(c[0], c[1]) + ' − ' + fstr(c[2], c[3]),
    c[4], c[5],
    [fstr(c[0] + c[2], c[1] + c[3]), fstr(c[4] + 1, c[5]), fstr(1, c[1] + c[3])],
    'f17_' + c.slice(0, 4).join('_'));
};

/* F18 Una fracción por un entero (6.º) */
CB.gen.fracciones.F18 = function (rng, D) {
  const den = CB.util.elegir(rng, [2, 3, 4, 5]);
  const num = CB.util.ent(rng, 1, den - 1);
  const k = den * CB.util.ent(rng, 1, (D === 1) ? 4 : 10);
  return {
    formato: 'teclado',
    consigna: fstr(num, den) + ' × ' + k,
    respuesta: (num * k) / den,
    expr: 'f18_' + num + '_' + den + '_' + k,
    diagnostico: false
  };
};

/* F19 La fracción de una fracción (6.º) */
CB.gen.fracciones.F19 = function (rng, D) {
  const casos = [[2, 2, 'la mitad de un medio', 1, 4],
                 [2, 3, 'la mitad de un tercio', 1, 6],
                 [2, 4, 'la mitad de un cuarto', 1, 8],
                 [3, 2, 'el tercio de un medio', 1, 6],
                 [2, 5, 'la mitad de un quinto', 1, 10],
                 [3, 3, 'el tercio de un tercio', 1, 9]];
  const c = CB.util.elegir(rng, casos);
  return itemFrac('¿Cuánto es ' + c[2] + '?', c[3], c[4],
    [fstr(1, c[0] + c[1]), fstr(2, c[4]), fstr(1, c[4] - 1)],
    'f19_' + c[0] + '_' + c[1]);
};

/* F20 La fracción mayor (6.º) */
CB.gen.fracciones.F20 = function (rng, D) {
  const candidatas = CB.util.barajar(
    [[1, 2], [2, 3], [3, 4], [1, 3], [3, 5], [5, 6], [1, 4], [4, 5], [2, 5], [5, 8]],
    rng).slice(0, 4);
  let mayor = candidatas[0], i;
  for (i = 1; i < candidatas.length; i++) {
    if (candidatas[i][0] * mayor[1] > mayor[0] * candidatas[i][1]) mayor = candidatas[i];
  }
  return itemFrac('Toca la fracción MAYOR.', mayor[0], mayor[1],
    candidatas.filter(function (f) { return f !== mayor; })
      .map(function (f) { return fstr(f[0], f[1]); }),
    'f20_' + candidatas.map(function (f) { return f.join('-'); }).join('_'));
};

/* 19c-gen-decimales.js — C1…C15 (cursos 4.º-6.º).
   REGLA DE ORO: cada decimal nace como entero escalado y se divide UNA vez
   entre 10 o 100. Así la respuesta y parseFloat(lo tecleado) son el mismo
   doble, y la igualdad estricta de responder() es exacta. Los ítems que se
   contestan con coma llevan conComa: el teclado saca la tecla. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.decimales = {};

const comaTxt = function (sc, esc) { return CB.gen.motor.coma(sc, esc); };
const decNum = function (sc, esc) { return CB.gen.motor.dec(sc, esc); };

/* C1 Las décimas (4.º) */
CB.gen.decimales.C1 = function (rng, D) {
  const u = CB.util.ent(rng, 0, (D === 1) ? 5 : 9);
  const d = CB.util.ent(rng, 1, 9);
  return {
    formato: 'teclado', conComa: true,
    consigna: 'Escribe con coma: ' + u + (u === 1 ? ' unidad y ' : ' unidades y ') +
              d + (d === 1 ? ' décima' : ' décimas') + '.',
    respuesta: decNum(u * 10 + d, 10),
    expr: 'c1_' + u + '_' + d,
    diagnostico: false
  };
};

/* C2 Las centésimas (4.º) */
CB.gen.decimales.C2 = function (rng, D) {
  const u = CB.util.ent(rng, 0, (D === 1) ? 5 : 9);
  const c = CB.util.ent(rng, 1, 99);
  return {
    formato: 'teclado', conComa: true,
    consigna: 'Escribe con coma: ' + u + (u === 1 ? ' unidad y ' : ' unidades y ') +
              c + (c === 1 ? ' centésima' : ' centésimas') + '.',
    respuesta: decNum(u * 100 + c, 100),
    expr: 'c2_' + u + '_' + c,
    diagnostico: false
  };
};

/* C3 Sumar decimales (4.º) */
CB.gen.decimales.C3 = function (rng, D) {
  const a = CB.util.ent(rng, 11, (D === 1) ? 50 : 89);   // décimas escaladas
  const b = CB.util.ent(rng, 11, 99 - a);
  return {
    formato: 'teclado', conComa: true,
    operacion: '+', operandos: [decNum(a, 10), decNum(b, 10)],
    consigna: comaTxt(a, 10) + ' + ' + comaTxt(b, 10),
    respuesta: decNum(a + b, 10),
    expr: 'c3_' + a + '_' + b,
    diagnostico: true
  };
};

/* C4 Restar decimales (4.º) */
CB.gen.decimales.C4 = function (rng, D) {
  const b = CB.util.ent(rng, 11, (D === 1) ? 40 : 80);
  const a = CB.util.ent(rng, b + 1, 99);
  return {
    formato: 'teclado', conComa: true,
    operacion: '-', operandos: [decNum(a, 10), decNum(b, 10)],
    consigna: comaTxt(a, 10) + ' − ' + comaTxt(b, 10),
    respuesta: decNum(a - b, 10),
    expr: 'c4_' + a + '_' + b,
    diagnostico: true
  };
};

/* C5 El dinero con coma (4.º) */
CB.gen.decimales.C5 = function (rng, D) {
  const a = CB.util.elegir(rng, [125, 150, 175, 225, 250, 275, 325, 350, 450, 550]);
  const b = CB.util.elegir(rng, [25, 50, 75, 125, 150, 225, 250]);
  return {
    formato: 'teclado', conComa: true,
    consigna: 'Un cuaderno cuesta ' + comaTxt(a, 100) + ' € y un lápiz ' +
              comaTxt(b, 100) + ' €. ¿Cuánto es en total?',
    operacion: '+', operandos: [decNum(a, 100), decNum(b, 100)],
    respuesta: decNum(a + b, 100),
    expr: 'c5_' + a + '_' + b,
    diagnostico: true
  };
};

/* C6 Comparar decimales (5.º): el clásico 3,5 contra 3,45 */
CB.gen.decimales.C6 = function (rng, D) {
  const ent = CB.util.ent(rng, 1, 9);
  const d1 = CB.util.ent(rng, 2, 9);
  const grupo = [
    ent * 100 + d1 * 10,                       // x,d0  (x,5)
    /* desde 2: restar 1 daría x,(d-1)9, que es EXACTAMENTE el tercero */
    ent * 100 + d1 * 10 - CB.util.ent(rng, 2, 9),
    ent * 100 + (d1 - 1) * 10 + 9,             // x,(d-1)9
    (ent - 1) * 100 + 99                       // (x-1),99
  ];
  const mayor = Math.max.apply(null, grupo);
  return {
    formato: 'opciones4',
    consigna: 'Toca el número MAYOR.',
    respuesta: comaTxt(mayor, 100),
    respuestaFraccion: true,                    /* respuesta-texto, como 'c20' */
    distractoresFijos: grupo.filter(function (v) { return v !== mayor; })
      .map(function (v) { return comaTxt(v, 100); }),
    expr: 'c6_' + grupo.join('_'),
    diagnostico: false
  };
};

/* C7 Sumar y restar decimales (5.º): centésimas */
CB.gen.decimales.C7 = function (rng, D) {
  const resta = rng() < 0.5;
  let a = CB.util.ent(rng, 101, (D === 1) ? 500 : 899);
  let b = CB.util.ent(rng, 101, 899);
  if (resta && b > a) { const t = a; a = b; b = t; }
  if (!resta && a + b > 999) b = 999 - a;
  return {
    formato: 'teclado', conComa: true,
    operacion: resta ? '-' : '+', operandos: [decNum(a, 100), decNum(b, 100)],
    consigna: comaTxt(a, 100) + (resta ? ' − ' : ' + ') + comaTxt(b, 100),
    respuesta: decNum(resta ? (a - b) : (a + b), 100),
    expr: 'c7_' + a + (resta ? 'm' : 'p') + b,
    diagnostico: true
  };
};

/* C8 Un decimal por un entero (5.º) */
CB.gen.decimales.C8 = function (rng, D) {
  const a = CB.util.ent(rng, 11, (D === 1) ? 40 : 99);   // décimas
  const k = CB.util.ent(rng, 2, 9);
  return {
    formato: 'teclado', conComa: true,
    operacion: '×', operandos: [decNum(a, 10), k],
    consigna: comaTxt(a, 10) + ' × ' + k,
    respuesta: decNum(a * k, 10),
    expr: 'c8_' + a + '_' + k,
    diagnostico: false
  };
};

/* C9 Decimal por y entre 10 y 100 (5.º). Al DIVIDIR se parte de décimas: las
   centésimas entre 10 darían milésimas, y la milésima no existe en el juego. */
CB.gen.decimales.C9 = function (rng, D) {
  const divide = rng() < 0.4;
  if (divide) {
    const sd = CB.util.ent(rng, 11, 99);                 // décimas: x,y
    return {
      formato: 'teclado', conComa: true,
      consigna: comaTxt(sd, 10) + ' ÷ 10',
      respuesta: decNum(sd, 100),
      expr: 'c9d' + sd,
      diagnostico: false
    };
  }
  const sc = CB.util.ent(rng, 101, 999);                 // centésimas: x,yz
  const pot = CB.util.elegir(rng, (D === 1) ? [10] : [10, 100]);
  return {
    formato: 'teclado', conComa: true,
    consigna: comaTxt(sc, 100) + ' × ' + pot,
    respuesta: decNum(sc, Math.max(1, 100 / pot)),
    expr: 'c9_' + sc + 'x' + pot,
    diagnostico: false
  };
};

/* C10 Un decimal entre un entero, exacto (5.º) */
CB.gen.decimales.C10 = function (rng, D) {
  const c = CB.util.ent(rng, 11, (D === 1) ? 30 : 99);   // cociente en décimas
  const d = CB.util.ent(rng, 2, 9);
  return {
    formato: 'teclado', conComa: true,
    operacion: '÷', operandos: [decNum(c * d, 10), d],
    consigna: comaTxt(c * d, 10) + ' ÷ ' + d,
    respuesta: decNum(c, 10),
    expr: 'c10_' + c + '_' + d,
    diagnostico: false
  };
};

/* C11 Redondear decimales (5.º) */
CB.gen.decimales.C11 = function (rng, D) {
  let sc = CB.util.ent(rng, 101, 899);
  if (sc % 10 === 0) sc += CB.util.ent(rng, 1, 9);
  if (sc % 100 === 50) sc += 1;                          // sin caso frontera
  const resp = Math.round(sc / 100);
  return {
    formato: 'teclado',
    consigna: 'Redondea ' + comaTxt(sc, 100) + ' a las unidades.',
    respuesta: resp,
    expr: 'c11_' + sc,
    diagnostico: false
  };
};

/* C12 Operaciones con decimales (6.º) */
CB.gen.decimales.C12 = function (rng, D) {
  const modo = CB.util.ent(rng, 1, 3);
  if (modo === 3) {
    const a3 = CB.util.ent(rng, 12, 60);                 // décimas
    const k3 = CB.util.ent(rng, 3, 12);
    return {
      formato: 'teclado', conComa: true,
      operacion: '×', operandos: [decNum(a3, 10), k3],
      consigna: comaTxt(a3, 10) + ' × ' + k3,
      respuesta: decNum(a3 * k3, 10),
      expr: 'c12x_' + a3 + '_' + k3,
      diagnostico: false
    };
  }
  const resta = modo === 2;
  let a = CB.util.ent(rng, 105, 985);
  let b = CB.util.ent(rng, 105, 985);
  if (resta && b > a) { const t = a; a = b; b = t; }
  if (!resta && a + b > 1999) b = 1999 - a;
  return {
    formato: 'teclado', conComa: true,
    operacion: resta ? '-' : '+', operandos: [decNum(a, 100), decNum(b, 100)],
    consigna: comaTxt(a, 100) + (resta ? ' − ' : ' + ') + comaTxt(b, 100),
    respuesta: decNum(resta ? (a - b) : (a + b), 100),
    expr: 'c12_' + a + (resta ? 'm' : 'p') + b,
    diagnostico: true
  };
};

/* C13 Dividir entre 0,5 y 0,25 (6.º): multiplicar disfrazado */
CB.gen.decimales.C13 = function (rng, D) {
  const par = CB.util.elegir(rng, [[5, 10, 2], [25, 100, 4]]);   // 0,5 → ×2
  const a = CB.util.ent(rng, 2, (D === 1) ? 12 : 30);
  return {
    formato: 'teclado',
    consigna: a + ' ÷ ' + comaTxt(par[0], par[1]),
    respuesta: a * par[2],
    expr: 'c13_' + a + '_' + par[0],
    diagnostico: false
  };
};

/* C14 Porcentaje, decimal y fracción (6.º) */
CB.gen.decimales.C14 = function (rng, D) {
  const pct = CB.util.elegir(rng, [10, 20, 25, 30, 40, 50, 60, 75, 80, 90]);
  return {
    formato: 'teclado', conComa: true,
    consigna: 'Escribe el ' + pct + ' % como número con coma.',
    respuesta: decNum(pct, 100),
    expr: 'c14_' + pct,
    diagnostico: false
  };
};

/* C15 El ticket de la compra (6.º) */
CB.gen.decimales.C15 = function (rng, D) {
  const precios = [75, 125, 150, 175, 225, 250, 325, 350, 425, 550];
  const a = CB.util.elegir(rng, precios);
  const b = CB.util.elegir(rng, precios);
  const c = CB.util.elegir(rng, precios);
  return {
    formato: 'teclado', conComa: true,
    consigna: 'El ticket: ' + comaTxt(a, 100) + ' €, ' + comaTxt(b, 100) +
              ' € y ' + comaTxt(c, 100) + ' €. ¿Cuánto es en total?',
    respuesta: decNum(a + b + c, 100),
    expr: 'c15_' + a + '_' + b + '_' + c,
    diagnostico: false
  };
};

/* 19d-gen-porcentajes.js — T1…T6 (6.º). Respuestas SIEMPRE enteras: los
   porcentajes se construyen desde la respuesta para que el reparto cuadre. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.porcentajes = {};

/* T1 El tanto por ciento */
CB.gen.porcentajes.T1 = function (rng, D) {
  const pct = CB.util.elegir(rng, (D === 1) ? [50, 100] : [10, 25, 50, 75, 100]);
  const base = CB.util.ent(rng, 2, 20) * (pct === 25 || pct === 75 ? 4 : (pct === 10 ? 10 : 2));
  const resp = (base * pct) / 100;
  const candidatos = [base - resp, resp + pct, Math.round(resp / 2), resp * 2,
                      resp + 5, resp + 1];
  const fijos = [];
  candidatos.forEach(function (v) {
    if (v > 0 && v !== resp && fijos.indexOf(v) === -1 && fijos.length < 3) fijos.push(v);
  });
  return {
    formato: 'opciones4',
    consigna: '¿Cuánto es el ' + pct + ' % de ' + base + '?',
    respuesta: resp,
    expr: 't1_' + pct + '_' + base,
    diagnostico: false,
    distractoresFijos: fijos
  };
};

/* T2 El 10 %, el 25 % y el 50 % de números grandes */
CB.gen.porcentajes.T2 = function (rng, D) {
  const pct = CB.util.elegir(rng, [10, 25, 50]);
  const paso = { 10: 10, 25: 4, 50: 2 }[pct];
  const base = CB.util.ent(rng, 3, (D === 1) ? 40 : 99) * paso;
  return {
    formato: 'teclado',
    consigna: '¿Cuánto es el ' + pct + ' % de ' + CB.gen.motor.sep(base) + '?',
    respuesta: (base * pct) / 100,
    expr: 't2_' + pct + '_' + base,
    diagnostico: true,
    operacion: '%', operandos: [base, pct]
  };
};

/* T3 El descuento */
CB.gen.porcentajes.T3 = function (rng, D) {
  const pct = CB.util.elegir(rng, [10, 20, 25, 50]);
  const paso = { 10: 10, 20: 5, 25: 4, 50: 2 }[pct];
  const precio = CB.util.ent(rng, 2, (D === 1) ? 20 : 90) * paso;
  return {
    formato: 'teclado',
    consigna: 'Cuesta ' + precio + ' € y tiene un ' + pct +
              ' % de descuento. ¿Cuánto pagas?',
    respuesta: precio - (precio * pct) / 100,
    expr: 't3_' + pct + '_' + precio,
    diagnostico: true,
    operacion: '%', operandos: [precio, pct]
  };
};

/* T4 La subida */
CB.gen.porcentajes.T4 = function (rng, D) {
  const pct = CB.util.elegir(rng, [10, 25, 50]);
  const paso = { 10: 10, 25: 4, 50: 2 }[pct];
  const precio = CB.util.ent(rng, 2, (D === 1) ? 20 : 80) * paso;
  return {
    formato: 'teclado',
    consigna: 'Costaba ' + precio + ' € y sube un ' + pct +
              ' %. ¿Cuánto cuesta ahora?',
    respuesta: precio + (precio * pct) / 100,
    expr: 't4_' + pct + '_' + precio,
    diagnostico: false
  };
};

/* T5 La proporción directa */
CB.gen.porcentajes.T5 = function (rng, D) {
  const unidad = CB.util.ent(rng, 2, (D === 1) ? 5 : 12);
  const n1 = CB.util.ent(rng, 2, 5);
  let n2 = CB.util.ent(rng, 2, 9);
  if (n2 === n1) n2 += 1;
  return {
    formato: 'teclado',
    consigna: n1 + ' cuadernos cuestan ' + (n1 * unidad) + ' €. ¿Cuánto cuestan ' +
              n2 + '?',
    respuesta: n2 * unidad,
    expr: 't5_' + unidad + '_' + n1 + '_' + n2,
    diagnostico: false
  };
};

/* T6 Cualquier porcentaje entero */
CB.gen.porcentajes.T6 = function (rng, D) {
  const pct = CB.util.ent(rng, 2, 30);
  const base = CB.util.ent(rng, 2, (D === 1) ? 6 : 9) * 100;
  return {
    formato: 'teclado',
    consigna: '¿Cuánto es el ' + pct + ' % de ' + CB.gen.motor.sep(base) + '?',
    respuesta: (base * pct) / 100,
    expr: 't6_' + pct + '_' + base,
    diagnostico: true,
    operacion: '%', operandos: [base, pct]
  };
};

/* 19e-gen-enteros.js — Z1…Z4 (6.º). La primera vez que el juego dice un
   número negativo, y siempre con contexto: termómetro, ascensor, recta. El
   teclado saca la tecla del signo con conSigno. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.enteros = {};

/* Z1 El termómetro */
CB.gen.enteros.Z1 = function (rng, D) {
  const desde = CB.util.ent(rng, (D === 1) ? 2 : 0, 9);
  const baja = CB.util.ent(rng, desde + 1, desde + ((D === 1) ? 6 : 15));
  return {
    formato: 'teclado', conSigno: true,
    consigna: 'Estaba a ' + desde + ' °C y baja ' + baja +
              ' grados. ¿A qué temperatura queda?',
    operacion: '-', operandos: [desde, baja],
    respuesta: desde - baja,
    expr: 'z1_' + desde + '_' + baja,
    diagnostico: true
  };
};

/* Z2 El ascensor */
CB.gen.enteros.Z2 = function (rng, D) {
  const planta = CB.util.ent(rng, 0, (D === 1) ? 3 : 6);
  const baja = CB.util.ent(rng, planta + 1, planta + 5);
  return {
    formato: 'teclado', conSigno: true,
    consigna: 'El ascensor está en la planta ' + planta + ' y baja ' + baja +
              ' plantas. ¿A qué planta llega?',
    operacion: '-', operandos: [planta, baja],
    respuesta: planta - baja,
    expr: 'z2_' + planta + '_' + baja,
    diagnostico: true
  };
};

/* Z3 Comparar enteros */
CB.gen.enteros.Z3 = function (rng, D) {
  const grupo = [];
  let k = 0;
  while (grupo.length < 4 && k < 60) {
    k++;
    const v = CB.util.ent(rng, 0, 20) - 10;
    if (grupo.indexOf(v) === -1) grupo.push(v);
  }
  const menor = Math.min.apply(null, grupo);
  return {
    formato: 'opciones4',
    consigna: 'Toca el número MENOR.',
    respuesta: menor,
    expr: 'z3_' + grupo.join('_'),
    diagnostico: false,
    distractoresFijos: grupo.filter(function (v) { return v !== menor; })
  };
};

/* Z4 La recta con negativos */
CB.gen.enteros.Z4 = function (rng, D) {
  const n = CB.util.ent(rng, 0, 18) - 9;
  const pidePosterior = rng() < 0.5;
  return {
    formato: 'teclado', conSigno: true,
    consigna: pidePosterior
      ? '¿Qué número va justo después del ' + n + '?'
      : '¿Qué número va justo antes del ' + n + '?',
    respuesta: pidePosterior ? n + 1 : n - 1,
    expr: 'z4_' + (pidePosterior ? 'p' : 'a') + n,
    diagnostico: false
  };
};

/* 19f-gen-medida.js — Sentido de la medida (3.2.0): B1…B15 (CB.gen.medida) y
   H1…H6 (CB.gen.tiempo). Regla de la casa: los decimales solo aparecen en la
   CONSIGNA desde 4.º-5.º y solo son RESPUESTA con conComa; el resto de
   respuestas son enteros. El reloj es un visual, nunca una imagen. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.medida = {};
CB.gen.tiempo = {};

/* Conversión entre dos unidades con factor entero: la mitad de las veces se
   pregunta en un sentido y la mitad en el otro. */
function itemConversion(rng, grande, chica, factor, nMax, D) {
  const alReves = rng() < 0.5;
  const n = CB.util.ent(rng, 2, (D === 1) ? Math.max(2, Math.ceil(nMax / 2)) : nMax);
  if (alReves) {
    return {
      formato: 'teclado',
      consigna: '¿Cuántos ' + grande + ' son ' + CB.gen.motor.sep(n * factor) + ' ' + chica + '?',
      operacion: '÷', operandos: [n * factor, factor],
      respuesta: n,
      expr: 'cv' + grande + n + 'r',
      diagnostico: true
    };
  }
  return {
    formato: 'teclado',
    consigna: n + ' ' + grande + ' son… ¿cuántos ' + chica + '?',
    operacion: '×', operandos: [n, factor],
    respuesta: n * factor,
    expr: 'cv' + grande + n,
    diagnostico: true,
    tablasCompletas: true
  };
}
CB.gen.medida._itemConversion = itemConversion;

/* B1 Medir con bloques (1.º) */
CB.gen.medida.B1 = function (rng, D) {
  const n = CB.util.ent(rng, 2, (D === 1) ? 6 : 10);
  return {
    formato: 'teclado',
    consigna: 'Cada bloque mide 1 centímetro. ¿Cuántos centímetros mide la barra?',
    visual: { tipo: 'fraccion', partes: n, sombreadas: n },
    respuesta: n,
    expr: 'b1_' + n,
    diagnostico: false
  };
};

/* B2 Centímetros y metros (2.º) */
CB.gen.medida.B2 = function (rng, D) {
  return itemConversion(rng, 'metros', 'centímetros', 100, 9, D);
};

/* B3 ¿Con qué se mide? (2.º) */
CB.gen.medida.B3 = function (rng, D) {
  const casos = [
    ['el agua de una botella', 'litros'],
    ['lo que pesa una sandía', 'kilos'],
    ['el largo de una cuerda', 'metros'],
    ['lo que dura el recreo', 'minutos'],
    ['lo que pesa una carta', 'gramos'],
    ['el alto de una puerta', 'metros'],
    ['la leche de una jarra', 'litros']
  ];
  const c = CB.util.elegir(rng, casos);
  const todas = ['litros', 'kilos', 'metros', 'minutos', 'gramos'];
  const fijos = CB.util.barajar(
    todas.filter(function (u) { return u !== c[1]; }), rng).slice(0, 3);
  return {
    formato: 'opciones4',
    consigna: '¿Con qué medirías ' + c[0] + '?',
    respuesta: c[1],
    respuestaFraccion: true,
    distractoresFijos: fijos,
    expr: 'b3_' + c[0].replace(/ /g, ''),
    diagnostico: false
  };
};

/* B4 De metros a centímetros (3.º) */
CB.gen.medida.B4 = function (rng, D) {
  return itemConversion(rng, 'metros', 'centímetros', 100, 9, D);
};

/* B5 Gramos y kilos (3.º) */
CB.gen.medida.B5 = function (rng, D) {
  return itemConversion(rng, 'kilos', 'gramos', 1000, 9, D);
};

/* B6 El perímetro (3.º) */
CB.gen.medida.B6 = function (rng, D) {
  const a = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  const b = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  return {
    formato: 'teclado',
    consigna: 'Un rectángulo mide ' + a + ' cm de largo y ' + b +
              ' cm de alto. ¿Cuántos centímetros mide su borde entero?',
    visual: { tipo: 'matriz', filas: b, columnas: a },
    respuesta: 2 * (a + b),
    expr: 'b6_' + a + '_' + b,
    diagnostico: false
  };
};

/* B7 Kilómetros y metros (4.º) */
CB.gen.medida.B7 = function (rng, D) {
  return itemConversion(rng, 'kilómetros', 'metros', 1000, 9, D);
};

/* B8 Litros y mililitros (4.º) */
CB.gen.medida.B8 = function (rng, D) {
  return itemConversion(rng, 'litros', 'mililitros', 1000, 9, D);
};

/* B9 Perímetros de figuras (4.º) */
CB.gen.medida.B9 = function (rng, D) {
  const n = CB.util.ent(rng, 3, (D === 1) ? 9 : 25);
  const figura = CB.util.elegir(rng, [
    ['un cuadrado', 4], ['un triángulo de lados iguales', 3],
    ['un rombo de lados iguales', 4]
  ]);
  return {
    formato: 'teclado',
    consigna: 'Cada lado de ' + figura[0] + ' mide ' + n +
              ' cm. ¿Cuál es su perímetro?',
    operacion: '×', operandos: [figura[1], n],
    respuesta: figura[1] * n,
    /* cuadrado y rombo comparten lados=4: la figura entra en la identidad (E147) */
    expr: 'b9_' + figura[0].split(' ')[1].charAt(0) + figura[1] + '_' + n,
    diagnostico: true,
    tablasCompletas: true
  };
};

/* B10 El sistema métrico (5.º): decimal en la pregunta, entero en la respuesta */
CB.gen.medida.B10 = function (rng, D) {
  const casos = [
    ['m', 'cm', 100, 10], ['km', 'm', 1000, 10], ['cm', 'mm', 10, 10]
  ];
  const c = CB.util.elegir(rng, casos);
  const decimas = CB.util.ent(rng, 11, (D === 1) ? 45 : 95);   // x,y
  return {
    formato: 'teclado',
    consigna: CB.gen.motor.coma(decimas, 10) + ' ' + c[0] + ' son… ¿cuántos ' +
              c[1] + '?',
    respuesta: (decimas * c[2]) / 10,
    expr: 'b10_' + c[0] + '_' + decimas,
    diagnostico: false
  };
};

/* B11 El área del rectángulo (5.º) */
CB.gen.medida.B11 = function (rng, D) {
  const a = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  const b = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  return {
    formato: 'teclado',
    consigna: 'Un rectángulo mide ' + a + ' cm por ' + b +
              ' cm. ¿Cuántos cuadrados de 1 cm caben dentro?',
    visual: { tipo: 'matriz', filas: b, columnas: a },
    operacion: '×', operandos: [a, b],
    respuesta: a * b,
    expr: 'b11_' + a + '_' + b,
    diagnostico: true,
    tablasCompletas: true
  };
};

/* B12 Masa y capacidad con coma (5.º) */
CB.gen.medida.B12 = function (rng, D) {
  const c = CB.util.elegir(rng, [['kg', 'gramos', 1000], ['l', 'mililitros', 1000]]);
  const decimas = CB.util.ent(rng, 11, (D === 1) ? 45 : 95);
  return {
    formato: 'teclado',
    consigna: CB.gen.motor.coma(decimas, 10) + ' ' + c[0] + ' son… ¿cuántos ' +
              c[1] + '?',
    respuesta: decimas * 100,
    expr: 'b12_' + c[0] + '_' + decimas,
    diagnostico: false
  };
};

/* B13 Área del cuadrado y del triángulo (6.º) */
CB.gen.medida.B13 = function (rng, D) {
  if (rng() < 0.5) {
    const l = CB.util.ent(rng, 2, (D === 1) ? 8 : 12);
    return {
      formato: 'teclado',
      consigna: 'Un cuadrado tiene lados de ' + l +
                ' cm. ¿Cuál es su área, en centímetros cuadrados?',
      respuesta: l * l,
      expr: 'b13c_' + l,
      diagnostico: false
    };
  }
  const base = CB.util.ent(rng, 2, (D === 1) ? 5 : 8) * 2;
  const altura = CB.util.ent(rng, 2, 9);
  return {
    formato: 'teclado',
    consigna: 'Un triángulo tiene ' + base + ' cm de base y ' + altura +
              ' cm de altura. ¿Cuál es su área, en centímetros cuadrados?',
    respuesta: (base * altura) / 2,
    expr: 'b13t_' + base + '_' + altura,
    diagnostico: false
  };
};

/* B14 Conversiones con coma (6.º): aquí la respuesta SÍ puede llevarla */
CB.gen.medida.B14 = function (rng, D) {
  if (rng() < 0.5) {
    const g = CB.util.ent(rng, 2, 9) * 100 + CB.util.ent(rng, 1, 9) * 10;
    return {
      formato: 'teclado', conComa: true,
      consigna: g + ' gramos son… ¿cuántos kilos?',
      respuesta: CB.gen.motor.dec(g, 1000) * 1,
      expr: 'b14g_' + g,
      diagnostico: false
    };
  }
  const centesimas = CB.util.ent(rng, 105, (D === 1) ? 500 : 985);
  return {
    formato: 'teclado',
    consigna: CB.gen.motor.coma(centesimas, 100) + ' km son… ¿cuántos metros?',
    respuesta: centesimas * 10,
    expr: 'b14k_' + centesimas,
    diagnostico: false
  };
};

/* B15 Problemas de medida (6.º) */
CB.gen.medida.B15 = function (rng, D) {
  const modo = CB.util.ent(rng, 1, 3);
  if (modo === 1) {
    const a = CB.util.ent(rng, 4, 30);
    const b = CB.util.ent(rng, 3, 20);
    return {
      formato: 'teclado',
      consigna: 'Un huerto rectangular mide ' + a + ' m por ' + b +
                ' m. ¿Cuántos metros de valla hacen falta para rodearlo?',
      respuesta: 2 * (a + b),
      expr: 'b15v_' + a + '_' + b,
      diagnostico: false
    };
  }
  if (modo === 2) {
    const vasos = CB.util.elegir(rng, [[1500, 250, 6], [1000, 250, 4], [1500, 500, 3], [2000, 250, 8], [1000, 200, 5]]);
    return {
      formato: 'teclado',
      consigna: 'Una botella tiene ' + CB.gen.motor.coma(vasos[0] / 100, 10) +
                ' litros. ¿Cuántos vasos de ' + vasos[1] + ' ml se pueden llenar?',
      respuesta: vasos[2],
      expr: 'b15b_' + vasos[0] + '_' + vasos[1],
      diagnostico: false
    };
  }
  const cajas = CB.util.ent(rng, 2, 9);
  const peso = CB.util.elegir(rng, [250, 500, 750]);
  return {
    formato: 'teclado',
    consigna: 'Cada caja pesa ' + peso + ' gramos. ¿Cuántos gramos pesan ' +
              cajas + ' cajas?',
    respuesta: cajas * peso,
    expr: 'b15c_' + cajas + '_' + peso,
    diagnostico: false
  };
};

/* ——— El tiempo: H1…H6 ——— */

function nombreHora(h, m) {
  if (m === 0) return h + ' en punto';
  if (m === 15) return h + ' y cuarto';
  if (m === 30) return h + ' y media';
  return (h % 12 + 1) + ' menos cuarto';
}
CB.gen.tiempo._nombreHora = nombreHora;

/* H1 La hora en punto (1.º) */
CB.gen.tiempo.H1 = function (rng, D) {
  const h = CB.util.ent(rng, 1, (D === 1) ? 6 : 12);
  return {
    formato: 'teclado',
    consigna: 'Mira el reloj. ¿Qué hora es? Escribe solo el número.',
    visual: { tipo: 'reloj', horas: h, minutos: 0 },
    respuesta: h,
    expr: 'h1_' + h,
    diagnostico: false
  };
};

/* H2 En punto y y media (2.º) */
CB.gen.tiempo.H2 = function (rng, D) {
  const h = CB.util.ent(rng, 1, 12);
  const m = (D === 1 || rng() < 0.5) ? 0 : 30;
  const resp = nombreHora(h, m);
  const fijos = [nombreHora(h, m === 0 ? 30 : 0),
                 nombreHora(h % 12 + 1, m),
                 nombreHora(h % 12 + 1, m === 0 ? 30 : 0)];
  return {
    formato: 'opciones4',
    consigna: '¿Qué hora marca el reloj?',
    visual: { tipo: 'reloj', horas: h, minutos: m },
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: fijos,
    expr: 'h2_' + h + '_' + m,
    diagnostico: false
  };
};

/* H3 Los cuartos (3.º) */
CB.gen.tiempo.H3 = function (rng, D) {
  const h = CB.util.ent(rng, 1, 12);
  const m = CB.util.elegir(rng, (D === 1) ? [15, 30] : [0, 15, 30, 45]);
  const resp = nombreHora(h, m);
  const otras = [0, 15, 30, 45].filter(function (x) { return x !== m; });
  const fijos = otras.map(function (x) { return nombreHora(h, x); });
  return {
    formato: 'opciones4',
    consigna: '¿Qué hora marca el reloj?',
    visual: { tipo: 'reloj', horas: h, minutos: m },
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: fijos,
    expr: 'h3_' + h + '_' + m,
    diagnostico: false
  };
};

/* H4 El reloj de minutos (4.º) */
CB.gen.tiempo.H4 = function (rng, D) {
  const h = CB.util.ent(rng, 1, 12);
  const m = CB.util.ent(rng, 1, 11) * 5;
  function txt(hh, mm) { return hh + ':' + (mm < 10 ? '0' : '') + mm; }
  const resp = txt(h, m);
  const fijos = [txt(h % 12 + 1, m), txt(h, (m + 5) % 60), txt(h, (m + 55) % 60)];
  return {
    formato: 'opciones4',
    consigna: '¿Qué hora marca el reloj?',
    visual: { tipo: 'reloj', horas: h, minutos: m },
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: fijos,
    expr: 'h4_' + h + '_' + m,
    diagnostico: false
  };
};

/* H5 Horas y minutos (5.º) */
CB.gen.tiempo.H5 = function (rng, D) {
  const h = CB.util.ent(rng, 1, (D === 1) ? 2 : 4);
  const m = CB.util.ent(rng, 0, 11) * 5;
  return {
    formato: 'teclado',
    consigna: '¿Cuántos minutos son ' + h + (h === 1 ? ' hora' : ' horas') +
              (m ? ' y ' + m + ' minutos' : '') + '?',
    operacion: '×', operandos: [h, 60],
    respuesta: h * 60 + m,
    expr: 'h5_' + h + '_' + m,
    diagnostico: false
  };
};

/* H6 Minutos y segundos (6.º) */
CB.gen.tiempo.H6 = function (rng, D) {
  if (rng() < 0.5) {
    const min = CB.util.ent(rng, 2, (D === 1) ? 5 : 10);
    return {
      formato: 'teclado',
      consigna: '¿Cuántos segundos son ' + min + ' minutos?',
      operacion: '×', operandos: [min, 60],
      respuesta: min * 60,
      expr: 'h6s_' + min,
      diagnostico: false
    };
  }
  const min2 = CB.util.ent(rng, 2, 9);
  return {
    formato: 'teclado',
    consigna: '¿Cuántos minutos son ' + (min2 * 60) + ' segundos?',
    operacion: '÷', operandos: [min2 * 60, 60],
    respuesta: min2,
    expr: 'h6m_' + min2,
    diagnostico: false
  };
};

/* 19g-gen-datos.js — Sentido estocástico (3.3.0): G1…G12 (CB.gen.datos) y
   A1…A7 (CB.gen.azar). Dos reglas de la casa: el color NUNCA lleva la
   información él solo (la consigna dice los recuentos con palabras, y las
   barras del gráfico se distinguen por su etiqueta, no por su tinte), y toda
   pregunta de azar tiene UNA respuesta inequívoca — «posible» a secas nunca es
   opción, porque cuando algo es seguro también es posible. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.datos = {};
CB.gen.azar = {};

/* Temas de los gráficos: 4 categorías por tema, en plural. Lista CERRADA. */
const TEMAS_DATOS = [
  ['perros', 'gatos', 'peces', 'pájaros'],
  ['manzanas', 'peras', 'plátanos', 'fresas'],
  ['canicas', 'cromos', 'puzles', 'cuentos'],
  ['coches', 'trenes', 'barcos', 'aviones']
];

/* Colores de las bolas de la bolsa, en femenino singular («bola roja»). */
const COLORES_BOLA = ['roja', 'azul', 'verde', 'amarilla', 'naranja', 'morada'];

/* Un gráfico de barras: nCats categorías de un tema, con valores DISTINTOS
   entre minV y maxV (distintos para que «el que más» y «el que menos» sean
   siempre inequívocos). Devuelve { filas, valores, nombres }. */
function hacerGrafico(rng, nCats, minV, maxV) {
  const tema = CB.util.elegir(rng, TEMAS_DATOS);
  const nombres = CB.util.barajar(tema.slice(), rng).slice(0, nCats);
  const posibles = [];
  let v;
  for (v = minV; v <= maxV; v++) posibles.push(v);
  const valores = CB.util.barajar(posibles, rng).slice(0, nCats);
  const filas = nombres.map(function (n, i) {
    return { nombre: n, valor: valores[i] };
  });
  return { filas: filas, valores: valores, nombres: nombres };
}
CB.gen.datos._hacerGrafico = hacerGrafico;

/* G1 El gráfico de los juguetes (1.º): leer una barra, valores pequeños. */
CB.gen.datos.G1 = function (rng, D) {
  const g = hacerGrafico(rng, 3, 1, (D === 1) ? 6 : 9);
  const i = CB.util.ent(rng, 0, 2);
  return {
    formato: 'teclado',
    consigna: 'Mira el gráfico. ¿Cuántos ' + g.nombres[i] + ' hay?',
    visual: { tipo: 'barras', filas: g.filas },
    respuesta: g.valores[i],
    datosGrafico: g.valores.slice(),
    expr: 'g1_' + g.nombres.join('-') + '_' + g.valores.join('-') + '_' + i,
    diagnostico: true
  };
};

/* G2 Leer el gráfico de barras (2.º): cuatro barras, valores mayores. */
CB.gen.datos.G2 = function (rng, D) {
  const g = hacerGrafico(rng, 4, 1, (D === 1) ? 8 : 12);
  const i = CB.util.ent(rng, 0, 3);
  return {
    formato: 'teclado',
    consigna: 'Mira el gráfico. ¿Cuántos ' + g.nombres[i] + ' hay?',
    visual: { tipo: 'barras', filas: g.filas },
    respuesta: g.valores[i],
    datosGrafico: g.valores.slice(),
    expr: 'g2_' + g.nombres.join('-') + '_' + g.valores.join('-') + '_' + i,
    diagnostico: true
  };
};

/* G3 El que más y el que menos (2.º): la respuesta es una CATEGORÍA (cadena,
   mecanismo 'c20'), y los valores distintos garantizan que es única. */
CB.gen.datos.G3 = function (rng, D) {
  const g = hacerGrafico(rng, 4, 1, (D === 1) ? 8 : 12);
  const buscaMax = rng() < 0.5;
  let mejor = 0, i;
  for (i = 1; i < 4; i++) {
    if (buscaMax ? g.valores[i] > g.valores[mejor]
                 : g.valores[i] < g.valores[mejor]) mejor = i;
  }
  return {
    formato: 'opciones4',
    consigna: 'Mira el gráfico. ¿De qué hay ' + (buscaMax ? 'MÁS' : 'MENOS') + '?',
    visual: { tipo: 'barras', filas: g.filas },
    respuesta: g.nombres[mejor],
    respuestaFraccion: true,
    distractoresFijos: g.nombres.filter(function (n, j) { return j !== mejor; }),
    expr: 'g3_' + g.nombres.join('-') + '_' + g.valores.join('-') + (buscaMax ? 'M' : 'm'),
    diagnostico: false
  };
};

/* G4 Los votos de la clase (3.º): sumar dos barras. */
CB.gen.datos.G4 = function (rng, D) {
  const g = hacerGrafico(rng, 4, 2, (D === 1) ? 8 : 12);
  const par = CB.util.barajar([0, 1, 2, 3], rng).slice(0, 2);
  const a = par[0], b = par[1];
  return {
    formato: 'teclado',
    consigna: 'Mira el gráfico. ¿Cuántos ' + g.nombres[a] + ' y ' +
              g.nombres[b] + ' hay entre los dos?',
    visual: { tipo: 'barras', filas: g.filas },
    operacion: '+', operandos: [g.valores[a], g.valores[b]],
    respuesta: g.valores[a] + g.valores[b],
    datosGrafico: g.valores.slice(),
    expr: 'g4_' + g.nombres.join('-') + '_' + g.valores.join('-') + '_' + a + b,
    diagnostico: true
  };
};

/* G5 ¿Cuántos más? (3.º): la diferencia entre dos barras. */
CB.gen.datos.G5 = function (rng, D) {
  const g = hacerGrafico(rng, 4, 1, (D === 1) ? 9 : 12);
  const par = CB.util.barajar([0, 1, 2, 3], rng).slice(0, 2);
  const a = (g.valores[par[0]] > g.valores[par[1]]) ? par[0] : par[1];
  const b = (a === par[0]) ? par[1] : par[0];
  return {
    formato: 'teclado',
    consigna: 'Mira el gráfico. ¿Cuántos ' + g.nombres[a] + ' hay MÁS que ' +
              g.nombres[b] + '?',
    visual: { tipo: 'barras', filas: g.filas },
    operacion: '-' /* ASCII: los consumidores comparan con '-', el − es solo de pintura */, operandos: [g.valores[a], g.valores[b]],
    respuesta: g.valores[a] - g.valores[b],
    datosGrafico: g.valores.slice(),
    expr: 'g5_' + g.nombres.join('-') + '_' + g.valores.join('-') + '_' + a + b,
    diagnostico: true
  };
};

/* G6 El pictograma (4.º): cada bloque vale 2, 5 o 10. */
CB.gen.datos.G6 = function (rng, D) {
  const escala = CB.util.elegir(rng, (D === 1) ? [2, 10] : [2, 5, 10]);
  const g = hacerGrafico(rng, 3, 1, (D === 1) ? 6 : 8);
  const i = CB.util.ent(rng, 0, 2);
  return {
    formato: 'teclado',
    consigna: 'En este gráfico cada bloque vale ' + escala +
              '. ¿Cuántos ' + g.nombres[i] + ' hay de verdad?',
    visual: { tipo: 'barras', filas: g.filas, escala: escala },
    operacion: '×', operandos: [g.valores[i], escala],
    respuesta: g.valores[i] * escala,
    tablasCompletas: true,
    expr: 'g6_' + escala + '_' + g.nombres.join('-') + '_' + g.valores.join('-') + '_' + i,
    diagnostico: true
  };
};

/* G7 La encuesta entera (4.º): el total de las cuatro barras. */
CB.gen.datos.G7 = function (rng, D) {
  const g = hacerGrafico(rng, 4, 2, (D === 1) ? 9 : 12);
  const total = g.valores[0] + g.valores[1] + g.valores[2] + g.valores[3];
  return {
    formato: 'teclado',
    consigna: 'Mira el gráfico. ¿Cuántos hay en total, sumando las cuatro barras?',
    visual: { tipo: 'barras', filas: g.filas },
    respuesta: total,
    datosGrafico: g.valores.slice(),
    expr: 'g7_' + g.nombres.join('-') + '_' + g.valores.join('-'),
    diagnostico: false
  };
};

/* ——— Ciclo 3: la media, la moda y el rango. ——— */

/* Una lista con moda ÚNICA: la moda aparece 3 veces y otros dos valores una.
   Los tres valores distintos salen de una baraja, no de un bucle de rechazo:
   todo while de src/ necesita cota, y aquí ni hace falta el while. */
function listaConModa(rng, maxV) {
  const posibles = [];
  let v;
  for (v = 1; v <= maxV; v++) posibles.push(v);
  const tres = CB.util.barajar(posibles, rng).slice(0, 3);
  const lista = CB.util.barajar([tres[0], tres[0], tres[0], tres[1], tres[2]], rng);
  return { lista: lista, moda: tres[0] };
}
CB.gen.datos._listaConModa = listaConModa;

/* Una lista de `k` valores cuya media es un entero EXACTO y cuyos valores se
   quedan todos en [1, topeValor]. Se separa en PARES (+d, −d): la suma no se
   mueve, así que nunca hace falta un valor «de cierre» que pueda salirse
   (la primera versión cerraba la suma con el último valor, y en un gráfico
   salían barras de 0 o de 14 bloques: una barra que miente). */
function listaConMedia(rng, k, maxMedia, topeValor) {
  const media = CB.util.ent(rng, 2, maxMedia);
  const holgura = Math.min(media - 1, topeValor - media);
  const lista = [];
  let i, d;
  for (i = 0; i < k; i++) lista.push(media);
  for (i = 0; i + 1 < k; i += 2) {
    d = holgura > 0 ? CB.util.ent(rng, 0, holgura) : 0;
    lista[i] += d;
    lista[i + 1] -= d;
  }
  return { lista: CB.util.barajar(lista, rng), media: media, suma: media * k };
}
CB.gen.datos._listaConMedia = listaConMedia;

function enLista(lista) {
  const partes = lista.map(String);
  return partes.slice(0, -1).join(', ') + ' y ' + partes[partes.length - 1];
}

/* G8 La moda (5.º) */
CB.gen.datos.G8 = function (rng, D) {
  const l = listaConModa(rng, (D === 1) ? 6 : 12);
  return {
    formato: 'teclado',
    consigna: 'Los goles de cinco partidos: ' + enLista(l.lista) +
              '. ¿Cuál es la moda, el número que más se repite?',
    respuesta: l.moda,
    datosGrafico: l.lista.slice(),
    expr: 'g8_' + l.lista.join('-'),
    diagnostico: true
  };
};

/* G9 La media (5.º) */
CB.gen.datos.G9 = function (rng, D) {
  const k = (D === 1) ? 3 : CB.util.elegir(rng, [3, 4, 5]);
  const l = listaConMedia(rng, k, (D === 1) ? 8 : 12, 20);
  return {
    formato: 'teclado',
    consigna: 'Los puntos de ' + k + ' partidas: ' + enLista(l.lista) +
              '. ¿Cuál es la media?',
    operacion: '÷', operandos: [l.suma, k],
    respuesta: l.media,
    sumaDatos: l.suma,
    expr: 'g9_' + l.lista.join('-'),
    diagnostico: true
  };
};

/* G10 El rango (5.º) */
CB.gen.datos.G10 = function (rng, D) {
  const posibles = [];
  let v;
  for (v = 2; v <= ((D === 1) ? 12 : 20); v++) posibles.push(v);
  const lista = CB.util.barajar(posibles, rng).slice(0, 4);
  const max = Math.max.apply(null, lista);
  const min = Math.min.apply(null, lista);
  return {
    formato: 'teclado',
    consigna: 'Las temperaturas de cuatro días: ' + enLista(lista) +
              ' grados. ¿Cuál es el rango: el mayor menos el menor?',
    operacion: '-' /* ASCII: los consumidores comparan con '-', el − es solo de pintura */, operandos: [max, min],
    respuesta: max - min,
    maxDato: max,
    expr: 'g10_' + lista.join('-'),
    diagnostico: true
  };
};

/* G11 La media del gráfico (6.º): la media de las barras, exacta. */
CB.gen.datos.G11 = function (rng, D) {
  const k = (D === 1) ? 3 : CB.util.elegir(rng, [3, 4]);
  const l = listaConMedia(rng, k, (D === 1) ? 8 : 11, 12);
  const tema = CB.util.elegir(rng, TEMAS_DATOS);
  const nombres = CB.util.barajar(tema.slice(), rng).slice(0, k);
  const filas = nombres.map(function (n, i) {
    return { nombre: n, valor: l.lista[i] };
  });
  return {
    formato: 'teclado',
    consigna: 'Mira el gráfico. ¿Cuál es la media de las ' + k + ' barras?',
    visual: { tipo: 'barras', filas: filas },
    operacion: '÷', operandos: [l.suma, k],
    respuesta: l.media,
    sumaDatos: l.suma,
    expr: 'g11_' + l.lista.join('-'),
    diagnostico: true
  };
};

/* G12 Media, moda y rango (6.º): una de las tres, dicha por su nombre. */
CB.gen.datos.G12 = function (rng, D) {
  const modo = CB.util.ent(rng, 1, 3);
  if (modo === 1) {
    const m = listaConMedia(rng, 4, (D === 1) ? 9 : 12, 20);
    return {
      formato: 'teclado',
      consigna: 'Estos son los datos: ' + enLista(m.lista) +
                '. ¿Cuál es la MEDIA?',
      operacion: '÷', operandos: [m.suma, 4],
      respuesta: m.media,
      sumaDatos: m.suma,
      expr: 'g12a_' + m.lista.join('-'),
      diagnostico: true
    };
  }
  if (modo === 2) {
    const mo = listaConModa(rng, 12);
    return {
      formato: 'teclado',
      consigna: 'Estos son los datos: ' + enLista(mo.lista) +
                '. ¿Cuál es la MODA?',
      respuesta: mo.moda,
      datosGrafico: mo.lista.slice(),
      expr: 'g12b_' + mo.lista.join('-'),
      diagnostico: true
    };
  }
  const posibles = [];
  let v;
  for (v = 3; v <= 20; v++) posibles.push(v);
  const lista = CB.util.barajar(posibles, rng).slice(0, 4);
  const max = Math.max.apply(null, lista);
  const min = Math.min.apply(null, lista);
  return {
    formato: 'teclado',
    consigna: 'Estos son los datos: ' + enLista(lista) +
              '. ¿Cuál es el RANGO?',
    operacion: '-' /* ASCII: los consumidores comparan con '-', el − es solo de pintura */, operandos: [max, min],
    respuesta: max - min,
    maxDato: max,
    expr: 'g12c_' + lista.join('-'),
    diagnostico: true
  };
};

/* ——— El azar: A1…A7. ——— */

/* A1 Seguro o imposible (1.º): la respuesta es un COLOR, nunca la palabra
   «posible» (cuando algo es seguro, también es posible: sería ambiguo). */
CB.gen.azar.A1 = function (rng, D) {
  const colores = CB.util.barajar(COLORES_BOLA.slice(0, 4), rng);
  if (D === 1 || rng() < 0.5) {
    return {
      formato: 'opciones4',
      consigna: 'En la bolsa todas las bolas son de color ' + colores[0] +
                '. Sacas una sin mirar. ¿De qué color saldrá SEGURO?',
      respuesta: colores[0],
      respuestaFraccion: true,
      distractoresFijos: [colores[1], colores[2], colores[3]],
      expr: 'a1s_' + colores[0],
      diagnostico: false
    };
  }
  return {
    formato: 'opciones4',
    consigna: 'En la bolsa hay bolas de color ' + colores[0] + ', ' +
              colores[1] + ' y ' + colores[2] +
              '. ¿De qué color es IMPOSIBLE que salga una bola?',
    respuesta: colores[3],
    respuestaFraccion: true,
    distractoresFijos: [colores[0], colores[1], colores[2]],
    expr: 'a1i_' + colores.join(''),
    diagnostico: false
  };
};

/* A2 La bolsa de las bolas (2.º): seguro, imposible o puede salir. En el modo
   «puede salir» la bolsa tiene DOS colores pero las opciones solo enseñan uno
   de ellos: la respuesta sigue siendo única. */
CB.gen.azar.A2 = function (rng, D) {
  const colores = CB.util.barajar(COLORES_BOLA.slice(), rng);
  const modo = CB.util.ent(rng, 1, (D === 1) ? 2 : 3);
  if (modo === 1) {
    return {
      formato: 'opciones4',
      consigna: 'Todas las bolas de la bolsa son de color ' + colores[0] +
                '. ¿De qué color saldrá SEGURO?',
      respuesta: colores[0],
      respuestaFraccion: true,
      distractoresFijos: [colores[1], colores[2], colores[3]],
      expr: 'a2s_' + colores[0],
      diagnostico: false
    };
  }
  if (modo === 2) {
    return {
      formato: 'opciones4',
      consigna: 'En la bolsa hay bolas de color ' + colores[0] + ', ' +
                colores[1] + ' y ' + colores[2] +
                '. ¿Qué color es IMPOSIBLE?',
      respuesta: colores[3],
      respuestaFraccion: true,
      distractoresFijos: [colores[0], colores[1], colores[2]],
      expr: 'a2i_' + colores.slice(0, 4).join(''),
      diagnostico: false
    };
  }
  return {
    formato: 'opciones4',
    consigna: 'En la bolsa hay bolas de color ' + colores[0] + ' y ' +
              colores[1] + '. ¿Cuál de estos colores PUEDE salir?',
    respuesta: colores[1],
    respuestaFraccion: true,
    distractoresFijos: [colores[2], colores[3], colores[4]],
    expr: 'a2p_' + colores.slice(0, 5).join(''),
    diagnostico: false
  };
};

/* Una bolsa con recuentos DISTINTOS de tres colores: el más y el menos
   probable son únicos. */
function bolsaConCuentas(rng, maxN) {
  const colores = CB.util.barajar(COLORES_BOLA.slice(0, 4), rng);
  const posibles = [];
  let v;
  for (v = 1; v <= maxN; v++) posibles.push(v);
  const cuentas = CB.util.barajar(posibles, rng).slice(0, 3);
  return { colores: colores, cuentas: cuentas };
}
CB.gen.azar._bolsaConCuentas = bolsaConCuentas;

function fraseBolsa(b) {
  return 'En la bolsa hay ' + b.cuentas[0] + ' bolas de color ' + b.colores[0] +
         ', ' + b.cuentas[1] + ' de color ' + b.colores[1] +
         ' y ' + b.cuentas[2] + ' de color ' + b.colores[2] + '.';
}

/* A3 Más probable (3.º) */
CB.gen.azar.A3 = function (rng, D) {
  const b = bolsaConCuentas(rng, (D === 1) ? 6 : 9);
  let mejor = 0, i;
  for (i = 1; i < 3; i++) if (b.cuentas[i] > b.cuentas[mejor]) mejor = i;
  return {
    formato: 'opciones4',
    consigna: fraseBolsa(b) + ' Sacas una sin mirar. ¿Qué color es MÁS probable?',
    respuesta: b.colores[mejor],
    respuestaFraccion: true,
    distractoresFijos: b.colores.filter(function (c, j) { return j !== mejor; }),
    expr: 'a3_' + b.colores.join('') + '_' + b.cuentas.join('-') + '_' + mejor,
    diagnostico: false
  };
};

/* A4 Menos probable (4.º): siempre entre colores que SÍ están en la bolsa
   (un color con cero bolas no es «menos probable»: es imposible). */
CB.gen.azar.A4 = function (rng, D) {
  const b = bolsaConCuentas(rng, (D === 1) ? 6 : 9);
  let peor = 0, i;
  for (i = 1; i < 3; i++) if (b.cuentas[i] < b.cuentas[peor]) peor = i;
  return {
    formato: 'opciones4',
    consigna: fraseBolsa(b) + ' Sacas una sin mirar. ¿Qué color es MENOS probable?',
    respuesta: b.colores[peor],
    respuestaFraccion: true,
    distractoresFijos: b.colores.filter(function (c, j) { return j !== peor; }),
    expr: 'a4_' + b.colores.join('') + '_' + b.cuentas.join('-') + '_' + peor,
    diagnostico: false
  };
};

/* Tres distractores de fracción DISTINTOS de la respuesta, sin repetirse:
   el mismo cierre con relleno que usa itemFrac en 19b. */
function fijosFraccion(resp, candidatos, num, den) {
  const fijos = [];
  let i, k = 1;
  for (i = 0; i < candidatos.length && fijos.length < 3; i++) {
    if (candidatos[i] !== resp && fijos.indexOf(candidatos[i]) === -1) {
      fijos.push(candidatos[i]);
    }
  }
  for (k = 1; k <= 20 && fijos.length < 3; k++) {   // cota: todo while/for la lleva
    const relleno = CB.gen.motor.fstr(num + k, den + k + 1);
    if (relleno !== resp && fijos.indexOf(relleno) === -1) fijos.push(relleno);
  }
  return fijos;
}
CB.gen.azar._fijosFraccion = fijosFraccion;

/* A5 La probabilidad como fracción (5.º) */
CB.gen.azar.A5 = function (rng, D) {
  const total = CB.util.ent(rng, 4, (D === 1) ? 6 : 10);
  const fav = CB.util.ent(rng, 1, total - 1);
  const color = CB.util.elegir(rng, COLORES_BOLA);
  const resp = CB.gen.motor.fstr(fav, total);
  const fijos = fijosFraccion(resp, [
    CB.gen.motor.fstr(total - fav, total),
    CB.gen.motor.fstr(total, fav),
    CB.gen.motor.fstr(fav, total - fav),
    CB.gen.motor.fstr(fav + 1, total)
  ], fav, total);
  return {
    formato: 'opciones4',
    consigna: 'En la bolsa hay ' + total + ' bolas y ' + fav +
              (fav === 1 ? ' es' : ' son') + ' de color ' + color +
              '. ¿Qué fracción dice la probabilidad de sacar una bola ' +
              color + '?',
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: fijos,
    expr: 'a5_' + fav + '_' + total + '_' + color,
    diagnostico: false
  };
};

/* A6 La regla de Laplace (6.º): dado o ruleta, casos favorables entre casos
   posibles, SIN simplificar (la fracción que se lee directamente). */
CB.gen.azar.A6 = function (rng, D) {
  if (D === 1 || rng() < 0.5) {
    const casos = CB.util.elegir(rng, [
      ['sacar un 6', 1], ['sacar un número par', 3], ['sacar más de 4', 2],
      ['sacar menos de 3', 2], ['sacar un 1 o un 2', 2]
    ]);
    const resp = CB.gen.motor.fstr(casos[1], 6);
    return {
      formato: 'opciones4',
      consigna: 'Tiras un dado del 1 al 6. ¿Qué probabilidad tiene ' +
                casos[0] + '? Escribe los casos favorables entre los posibles.',
      respuesta: resp,
      respuestaFraccion: true,
      distractoresFijos: fijosFraccion(resp, [
        CB.gen.motor.fstr(6 - casos[1], 6),
        CB.gen.motor.fstr(6, casos[1]),
        CB.gen.motor.fstr(casos[1] + 1, 6)
      ], casos[1], 6),
      expr: 'a6d_' + casos[1] + '_' + casos[0].replace(/ /g, ''),
      diagnostico: false
    };
  }
  const partes = CB.util.elegir(rng, [4, 5, 8, 10]);
  const pintadas = CB.util.ent(rng, 1, partes - 1);
  const resp = CB.gen.motor.fstr(pintadas, partes);
  return {
    formato: 'opciones4',
    consigna: 'Una ruleta tiene ' + partes + ' partes iguales y ' + pintadas +
              (pintadas === 1 ? ' está pintada' : ' están pintadas') +
              '. ¿Qué probabilidad hay de que pare en una parte pintada?',
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: fijosFraccion(resp, [
      CB.gen.motor.fstr(partes - pintadas, partes),
      CB.gen.motor.fstr(partes, pintadas),
      CB.gen.motor.fstr(pintadas + 1, partes)
    ], pintadas, partes),
    expr: 'a6r_' + pintadas + '_' + partes,
    diagnostico: false
  };
};

/* A7 Las veces que saldrá (6.º): frecuencia esperada de un experimento. */
CB.gen.azar.A7 = function (rng, D) {
  const modo = CB.util.ent(rng, 1, (D === 1) ? 2 : 3);
  if (modo === 1) {
    const k = CB.util.ent(rng, 5, 30) * 2;
    return {
      formato: 'teclado',
      consigna: 'Tiras una moneda ' + k + ' veces. Si el azar reparte por ' +
                'igual, ¿cuántas caras te tocan?',
      operacion: '÷', operandos: [k, 2],
      respuesta: k / 2,
      totalTiradas: k,
      expr: 'a7m_' + k,
      diagnostico: true
    };
  }
  if (modo === 2) {
    const k6 = CB.util.ent(rng, 2, 10) * 6;
    const cara = CB.util.ent(rng, 1, 6);
    return {
      formato: 'teclado',
      consigna: 'Tiras un dado ' + k6 + ' veces. Si el azar reparte por ' +
                'igual, ¿cuántas veces te toca el ' + cara + '?',
      operacion: '÷', operandos: [k6, 6],
      respuesta: k6 / 6,
      totalTiradas: k6,
      expr: 'a7d_' + k6 + '_' + cara,
      diagnostico: true
    };
  }
  const k4 = CB.util.ent(rng, 3, 15) * 4;
  return {
    formato: 'teclado',
    consigna: 'Una ruleta tiene 4 partes iguales y la giras ' + k4 +
              ' veces. Si el azar reparte por igual, ¿cuántas veces para ' +
              'en cada parte?',
    operacion: '÷', operandos: [k4, 4],
    respuesta: k4 / 4,
    totalTiradas: k4,
    expr: 'a7r_' + k4,
    diagnostico: true
  };
};

/* 19h-gen-algebra.js — Sentido algebraico (3.4.0): U1…U6 (CB.gen.patrones,
   series y pensamiento computacional) y X1…X6 (CB.gen.algebra, igualdades con
   hueco e incógnita). La regla heredada del azar sigue mandando: toda pregunta
   tiene UNA respuesta inequívoca — el salto de una serie nunca es 0, y los
   campos ultimoTermino/salto/factorSerie permiten RECONSTRUIR la serie, que es
   lo que mide el guardián E142. Los campos sumandoConocido/resultadoIgualdad
   alimentan E-X-SUMA-LOS-DOS y solo se declaran cuando «sumar los dos números
   visibles» NO coincide con la respuesta. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.patrones = {};
CB.gen.algebra = {};

/* Una serie aritmética de `n` términos con salto CON SIGNO (nunca 0). */
function serieDeSalto(inicio, salto, n) {
  const t = [];
  let i;
  for (i = 0; i < n; i++) t.push(inicio + i * salto);
  return t;
}
CB.gen.patrones._serieDeSalto = serieDeSalto;

function fraseSerie(terminos) {
  return terminos.join(', ') + ', …';
}

/* U1 Seguir la serie (1.º): sumar 1, 2 o 3, sin pasar de 20. */
CB.gen.patrones.U1 = function (rng, D) {
  const salto = CB.util.ent(rng, 1, (D === 1) ? 2 : 3);
  const inicio = CB.util.ent(rng, 0, 20 - 4 * salto);
  const t = serieDeSalto(inicio, salto, 4);
  return {
    formato: 'teclado',
    consigna: 'Sigue la serie: ' + fraseSerie(t) + ' ¿Qué número viene después?',
    respuesta: t[3] + salto,
    ultimoTermino: t[3],
    salto: salto,
    expr: 'u1_' + inicio + '_' + salto,
    diagnostico: true
  };
};

/* U2 La serie que baja (2.º): el salto viaja con signo. */
CB.gen.patrones.U2 = function (rng, D) {
  const paso = CB.util.elegir(rng, (D === 1) ? [1, 2] : [2, 5, 10]);
  const inicio = CB.util.ent(rng, 4 * paso + paso, 99);
  const t = serieDeSalto(inicio, -paso, 4);
  return {
    formato: 'teclado',
    consigna: 'La serie baja: ' + fraseSerie(t) + ' ¿Qué número viene después?',
    respuesta: t[3] - paso,
    ultimoTermino: t[3],
    salto: -paso,
    expr: 'u2_' + inicio + '_' + paso,
    diagnostico: true
  };
};

/* U3 La serie y su salto (3.º): seguirla, o decir de cuánto en cuánto va. */
CB.gen.patrones.U3 = function (rng, D) {
  const salto = CB.util.ent(rng, 3, 9);
  const inicio = CB.util.ent(rng, 1, 900);
  const t = serieDeSalto(inicio, salto, 4);
  if (D === 1 || rng() < 0.6) {
    return {
      formato: 'teclado',
      consigna: 'Sigue la serie: ' + fraseSerie(t) + ' ¿Qué número viene después?',
      respuesta: t[3] + salto,
      ultimoTermino: t[3],
      salto: salto,
      expr: 'u3a_' + inicio + '_' + salto,
      diagnostico: true
    };
  }
  return {
    formato: 'teclado',
    consigna: 'Mira la serie: ' + fraseSerie(t) + ' ¿De cuánto en cuánto va?',
    respuesta: salto,
    expr: 'u3b_' + inicio + '_' + salto,
    diagnostico: true
  };
};

/* U4 El robot de la cuadrícula (4.º): pensamiento computacional. El robot
   ejecuta instrucciones sobre una fila de 10 casillas y nunca se sale. */
CB.gen.patrones.U4 = function (rng, D) {
  const inicio = CB.util.ent(rng, 1, 5);
  const avanza = CB.util.ent(rng, 2, 10 - inicio);
  const retro = (D === 1) ? 0 : CB.util.ent(rng, 1, inicio + avanza - 1);
  return {
    formato: 'teclado',
    consigna: 'El robot está en la casilla ' + inicio + ' de una fila de 10. ' +
              'Avanza ' + avanza + (avanza === 1 ? ' casilla' : ' casillas') +
              (retro ? ' y retrocede ' + retro + (retro === 1 ? ' casilla' : ' casillas') : '') +
              '. ¿En qué casilla acaba?',
    visual: { tipo: 'fila', total: 10, marcada: inicio },
    respuesta: inicio + avanza - retro,
    expr: 'u4_' + inicio + '_' + avanza + '_' + retro,
    diagnostico: true
  };
};

/* U5 La serie de multiplicar (5.º) */
CB.gen.patrones.U5 = function (rng, D) {
  const factor = (D === 1) ? 2 : CB.util.elegir(rng, [2, 3]);
  const inicio = CB.util.ent(rng, 2, (factor === 2) ? 50 : 12);
  const t = [inicio, inicio * factor, inicio * factor * factor,
             inicio * factor * factor * factor];
  return {
    formato: 'teclado',
    consigna: 'La serie multiplica: ' + fraseSerie(t) + ' ¿Qué número viene después?',
    respuesta: t[3] * factor,
    ultimoTermino: t[3],
    factorSerie: factor,
    expr: 'u5_' + inicio + '_' + factor,
    diagnostico: true
  };
};

/* U6 El término del lugar N (6.º): la regla general de una serie aritmética. */
CB.gen.patrones.U6 = function (rng, D) {
  const a = CB.util.ent(rng, 1, 20);
  const d = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  const lugar = CB.util.ent(rng, 5, (D === 1) ? 8 : 12);
  const t = serieDeSalto(a, d, 3);
  return {
    formato: 'teclado',
    consigna: 'Una serie empieza así: ' + fraseSerie(t) + ' Suma ' + d +
              ' cada vez. ¿Qué número ocupa el lugar ' + lugar + '?',
    respuesta: a + d * (lugar - 1),
    expr: 'u6_' + a + '_' + d + '_' + lugar,
    diagnostico: true
  };
};

/* ——— Las igualdades con hueco y la incógnita: X1…X6. ——— */

/* X1 El hueco de la suma (1.º) */
CB.gen.algebra.X1 = function (rng, D) {
  const c = CB.util.ent(rng, (D === 1) ? 5 : 8, (D === 1) ? 10 : 20);
  const a = CB.util.ent(rng, 1, c - 1);
  return {
    formato: 'teclado',
    consigna: 'Busca el número del hueco: ' + a + ' + □ = ' + c + '.',
    respuesta: c - a,
    sumandoConocido: a,
    resultadoIgualdad: c,
    expr: 'x1_' + a + '_' + c,
    diagnostico: true
  };
};

/* X2 El hueco de la resta (2.º): el hueco puede estar en el sustraendo o en
   el minuendo. Con el hueco en el minuendo la respuesta ES la suma de los dos
   números visibles, así que ahí NO se declaran los campos del error. */
CB.gen.algebra.X2 = function (rng, D) {
  if (D === 1 || rng() < 0.5) {
    const m = CB.util.ent(rng, (D === 1) ? 6 : 12, (D === 1) ? 20 : 99);
    const r = CB.util.ent(rng, 1, m - 1);
    return {
      formato: 'teclado',
      consigna: 'Busca el número del hueco: ' + m + ' − □ = ' + r + '.',
      respuesta: m - r,
      sumandoConocido: m,
      resultadoIgualdad: r,
      expr: 'x2a_' + m + '_' + r,
      diagnostico: true
    };
  }
  const b = CB.util.ent(rng, 1, 50);
  const r = CB.util.ent(rng, 1, 99 - b);
  return {
    formato: 'teclado',
    consigna: 'Busca el número del hueco: □ − ' + b + ' = ' + r + '.',
    respuesta: b + r,
    expr: 'x2b_' + b + '_' + r,
    diagnostico: true
  };
};

/* X3 El hueco de multiplicar (3.º): las tablas al revés. */
CB.gen.algebra.X3 = function (rng, D) {
  const a = CB.util.ent(rng, 2, (D === 1) ? 5 : 9);
  const h = CB.util.ent(rng, 2, 9);
  return {
    formato: 'teclado',
    consigna: 'Busca el número del hueco: ' + a + ' × □ = ' + (a * h) + '.',
    respuesta: h,
    sumandoConocido: a,
    resultadoIgualdad: a * h,
    tablasCompletas: true,
    expr: 'x3_' + a + '_' + h,
    diagnostico: true
  };
};

/* X4 El hueco con dos operaciones (4.º): a un lado el hueco, al otro un
   producto que hay que calcular primero. */
CB.gen.algebra.X4 = function (rng, D) {
  const c = CB.util.ent(rng, 3, (D === 1) ? 6 : 9);
  const d = CB.util.ent(rng, 3, (D === 1) ? 6 : 9);
  const p = c * d;
  if (D === 1 || rng() < 0.6) {
    const b = CB.util.ent(rng, 1, p - 1);
    return {
      formato: 'teclado',
      consigna: 'Busca el número del hueco: □ + ' + b + ' = ' + c + ' × ' + d + '.',
      respuesta: p - b,
      sumandoConocido: b,
      resultadoIgualdad: p,
      expr: 'x4a_' + b + '_' + c + '_' + d,
      diagnostico: true
    };
  }
  const b = CB.util.ent(rng, 1, 99);
  return {
    formato: 'teclado',
    consigna: 'Busca el número del hueco: □ − ' + b + ' = ' + c + ' × ' + d + '.',
    respuesta: p + b,
    expr: 'x4b_' + b + '_' + c + '_' + d,
    diagnostico: true
  };
};

/* X5 La incógnita x (5.º): la letra ya tiene nombre. */
CB.gen.algebra.X5 = function (rng, D) {
  const modo = (D === 1) ? 1 : CB.util.ent(rng, 1, 3);
  if (modo === 1) {
    const a = CB.util.ent(rng, 10, (D === 1) ? 40 : 400);
    const x = CB.util.ent(rng, 10, (D === 1) ? 50 : 500);
    return {
      formato: 'teclado',
      consigna: 'La incógnita: x + ' + a + ' = ' + (x + a) + '. ¿Cuánto vale x?',
      respuesta: x,
      sumandoConocido: a,
      resultadoIgualdad: x + a,
      expr: 'x5a_' + a + '_' + x,
      diagnostico: true
    };
  }
  if (modo === 2) {
    const a = CB.util.ent(rng, 10, 300);
    const c = CB.util.ent(rng, 10, 400);
    return {
      formato: 'teclado',
      consigna: 'La incógnita: x − ' + a + ' = ' + c + '. ¿Cuánto vale x?',
      respuesta: a + c,
      expr: 'x5b_' + a + '_' + c,
      diagnostico: true
    };
  }
  const a = CB.util.ent(rng, 3, 12);
  const x = CB.util.ent(rng, 4, 50);
  return {
    formato: 'teclado',
    consigna: 'La incógnita: ' + a + ' · x = ' + (a * x) + '. ¿Cuánto vale x?',
    respuesta: x,
    sumandoConocido: a,
    resultadoIgualdad: a * x,
    expr: 'x5c_' + a + '_' + x,
    diagnostico: true
  };
};

/* X6 La incógnita en las cuatro (6.º) */
CB.gen.algebra.X6 = function (rng, D) {
  const modo = (D === 1) ? 1 : CB.util.ent(rng, 1, 3);
  if (modo === 1) {
    const a = CB.util.ent(rng, 3, 15);
    const x = CB.util.ent(rng, 6, 60);
    return {
      formato: 'teclado',
      consigna: 'La incógnita: ' + a + ' · x = ' + (a * x) + '. ¿Cuánto vale x?',
      respuesta: x,
      sumandoConocido: a,
      resultadoIgualdad: a * x,
      expr: 'x6a_' + a + '_' + x,
      diagnostico: true
    };
  }
  if (modo === 2) {
    const a = CB.util.ent(rng, 3, 9);
    const c = CB.util.ent(rng, 4, 30);
    return {
      formato: 'teclado',
      consigna: 'La incógnita: x ÷ ' + a + ' = ' + c + '. ¿Cuánto vale x?',
      respuesta: a * c,
      sumandoConocido: a,
      resultadoIgualdad: c,
      expr: 'x6b_' + a + '_' + c,
      diagnostico: true
    };
  }
  const a = CB.util.ent(rng, 25, 400);
  const c = CB.util.ent(rng, 25, 500);
  return {
    formato: 'teclado',
    consigna: 'La incógnita: x − ' + a + ' = ' + c + '. ¿Cuánto vale x?',
    respuesta: a + c,
    expr: 'x6c_' + a + '_' + c,
    diagnostico: true
  };
};

/* 19i-gen-espacial.js — Sentido espacial (3.4.0): J1…J7 (CB.gen.geometria,
   figuras, ángulos y cuerpos) y K1…K6 (CB.gen.espacio, posición, simetría y
   coordenadas). Tres reglas de la casa: el color nunca lleva la información
   (las casillas se distinguen por su LETRA, los ángulos por sus grados); toda
   figura dibujada tiene lados rectos, porque el vóxel no tiene curvas (el
   círculo no aparece dibujado jamás); y toda pregunta de coordenadas declara
   su convenio en la consigna — primero la columna, después la fila, y la fila
   1 es la de abajo — para que la respuesta sea inequívoca por construcción. */

var CB = CB || {};
CB.gen = CB.gen || {};
CB.gen.geometria = {};
CB.gen.espacio = {};

/* Las cuatro figuras dibujables. Lista CERRADA: son las que CB.ui.figuraPlana
   sabe pintar. lados === vértices en todo polígono; se pregunta por ambos. */
const FIGURAS_PLANAS = [
  { nombre: 'cuadrado',   lados: 4 },
  { nombre: 'rectángulo', lados: 4 },
  { nombre: 'triángulo',  lados: 3 },
  { nombre: 'rombo',      lados: 4 }
];

/* Polígonos por número de lados (4.º, solo de palabra). */
const POLIGONOS_LADOS = [
  ['el triángulo', 3], ['el cuadrilátero', 4], ['el pentágono', 5],
  ['el hexágono', 6], ['el octógono', 8]
];

/* Cuerpos geométricos: nombre, caras, aristas y vértices. */
const CUERPOS_GEO = [
  ['un cubo', 6, 12, 8],
  ['una pirámide de base cuadrada', 5, 8, 5],
  ['un prisma de base triangular', 5, 9, 6]
];

/* Tipos de ángulo con los grados que los dibujan. «llano» incluido: 180 se ve. */
const ANGULOS_TIPO = [
  ['agudo', [30, 45, 60]], ['recto', [90]],
  ['obtuso', [120, 135, 150]], ['llano', [180]]
];

/* Giros y sus grados. La vuelta entera se da como ANCLA en la consigna, así
   que no se pregunta nunca por ella. */
const VUELTAS_GIRO = [
  ['un cuarto de vuelta', 90], ['media vuelta', 180], ['tres cuartos de vuelta', 270]
];

/* Figuras y sus ejes de simetría, descritas sin ambigüedad. */
const SIMETRIAS_FIGURA = [
  ['un cuadrado', 4],
  ['un rectángulo que no es cuadrado', 2],
  ['un triángulo equilátero, con los tres lados iguales', 3],
  ['un rombo que no es cuadrado', 2]
];

/* Letras para las casillas: mayúsculas bien distintas entre sí. */
const LETRAS_CASILLA = ['A', 'B', 'C', 'D', 'E', 'H', 'J', 'L', 'M', 'P',
                        'R', 'S', 'T', 'U', 'V', 'Z'];

/* J1 ¿Qué figura es? (1.º) */
CB.gen.geometria.J1 = function (rng, D) {
  const fig = FIGURAS_PLANAS[CB.util.ent(rng, 0, (D === 1) ? 2 : 3)];
  return {
    formato: 'opciones4',
    consigna: 'Mira la figura. ¿Cómo se llama?',
    visual: { tipo: 'figura', nombre: fig.nombre },
    respuesta: fig.nombre,
    respuestaFraccion: true,
    distractoresFijos: FIGURAS_PLANAS.map(function (f) { return f.nombre; })
      .filter(function (n) { return n !== fig.nombre; }),
    expr: 'j1_' + fig.nombre,
    diagnostico: false
  };
};

/* J2 Lados y vértices (2.º) */
CB.gen.geometria.J2 = function (rng, D) {
  const fig = CB.util.elegir(rng, FIGURAS_PLANAS);
  const porVertices = (D !== 1) && rng() < 0.5;
  return {
    formato: 'teclado',
    consigna: 'Mira la figura. ¿Cuántos ' +
              (porVertices ? 'vértices (esquinas)' : 'lados') + ' tiene?',
    visual: { tipo: 'figura', nombre: fig.nombre },
    respuesta: fig.lados,
    expr: 'j2_' + fig.nombre + (porVertices ? 'v' : 'l'),
    diagnostico: true
  };
};

/* J3 Recto, agudo, obtuso o llano (3.º): el ángulo se dibuja y la respuesta
   es su nombre — nunca dos nombres verdaderos a la vez. */
CB.gen.geometria.J3 = function (rng, D) {
  const tipo = ANGULOS_TIPO[CB.util.ent(rng, 0, (D === 1) ? 2 : 3)];
  const grados = CB.util.elegir(rng, tipo[1]);
  return {
    formato: 'opciones4',
    consigna: 'Mira el ángulo. ¿Cómo es?',
    visual: { tipo: 'angulo', grados: grados },
    respuesta: tipo[0],
    respuestaFraccion: true,
    distractoresFijos: ANGULOS_TIPO.map(function (t) { return t[0]; })
      .filter(function (n) { return n !== tipo[0]; }),
    expr: 'j3_' + grados,
    diagnostico: false
  };
};

/* J4 Las figuras por sus lados (4.º) */
CB.gen.geometria.J4 = function (rng, D) {
  const p = CB.util.elegir(rng, POLIGONOS_LADOS);
  const otros = POLIGONOS_LADOS.map(function (q) { return q[0]; })
    .filter(function (n) { return n !== p[0]; });
  return {
    formato: 'opciones4',
    consigna: 'Una figura plana tiene ' + p[1] +
              ' lados rectos. ¿Cómo se llama?',
    respuesta: p[0],
    respuestaFraccion: true,
    distractoresFijos: CB.util.barajar(otros, rng).slice(0, 3),
    expr: 'j4_' + p[1],
    diagnostico: false
  };
};

/* J5 Caras, aristas y vértices (5.º): los cuerpos, de palabra. */
CB.gen.geometria.J5 = function (rng, D) {
  const cuerpo = (D === 1) ? CUERPOS_GEO[0] : CB.util.elegir(rng, CUERPOS_GEO);
  const preguntas = [['caras', 'Cuántas', 1], ['aristas', 'Cuántas', 2],
                     ['vértices', 'Cuántos', 3]];
  const p = CB.util.elegir(rng, preguntas);
  return {
    formato: 'teclado',
    consigna: 'Piensa en ' + cuerpo[0] + '. ¿' + p[1] + ' ' + p[0] + ' tiene?',
    respuesta: cuerpo[p[2]],
    expr: 'j5_' + cuerpo[0].replace(/ /g, '') + '_' + p[0],
    diagnostico: true
  };
};

/* J6 El tercer ángulo (6.º) */
CB.gen.geometria.J6 = function (rng, D) {
  const a = CB.util.ent(rng, 20, (D === 1) ? 60 : 80);
  const b = CB.util.ent(rng, 20, 150 - a);
  return {
    formato: 'teclado',
    consigna: 'Los ángulos de un triángulo suman 180 grados. Dos de ellos ' +
              'miden ' + a + ' y ' + b + ' grados. ¿Cuánto mide el tercero?',
    respuesta: 180 - a - b,
    anguloA: a,
    anguloB: b,
    expr: 'j6_' + a + '_' + b,
    diagnostico: true
  };
};

/* J7 Los grados de la vuelta (6.º) */
CB.gen.geometria.J7 = function (rng, D) {
  const v = VUELTAS_GIRO[CB.util.ent(rng, 0, (D === 1) ? 1 : 2)];
  return {
    formato: 'teclado',
    consigna: 'Una vuelta entera son 360 grados. ¿Cuántos grados ' +
              (v[1] === 90 ? 'es ' : 'son ') + v[0] + '?',
    respuesta: v[1],
    expr: 'j7_' + v[1],
    diagnostico: true
  };
};

/* ——— El espacio: K1…K6. ——— */

/* Una cuadrícula de letras de nc × nf casillas, todas distintas. Las filas
   van EN ORDEN LÓGICO: celdas[0] es la fila 1, la de abajo. */
function cuadriculaDeLetras(rng, nc, nf) {
  const letras = CB.util.barajar(LETRAS_CASILLA.slice(), rng).slice(0, nc * nf);
  const celdas = [];
  let f, c;
  for (f = 0; f < nf; f++) {
    const fila = [];
    for (c = 0; c < nc; c++) fila.push(letras[f * nc + c]);
    celdas.push(fila);
  }
  return celdas;
}
CB.gen.espacio._cuadriculaDeLetras = cuadriculaDeLetras;

/* Tres distractores de letra, empezando por la casilla de coordenadas
   INVERTIDAS si existe y es otra: es el error que la pregunta enseña a evitar. */
function fijosDeLetras(rng, celdas, resp, invertida) {
  const fijos = [];
  if (invertida != null && invertida !== resp) fijos.push(invertida);
  const resto = [];
  celdas.forEach(function (fila) {
    fila.forEach(function (l) {
      if (l && l !== resp && fijos.indexOf(l) === -1) resto.push(l);
    });
  });
  const mezcla = CB.util.barajar(resto, rng);
  let i;
  for (i = 0; i < mezcla.length && fijos.length < 3; i++) fijos.push(mezcla[i]);
  return fijos;
}
CB.gen.espacio._fijosDeLetras = fijosDeLetras;

/* K1 La posición en la fila (1.º): reutiliza la fila de vagonetas. */
CB.gen.espacio.K1 = function (rng, D) {
  const total = CB.util.ent(rng, 5, (D === 1) ? 6 : 9);
  const pos = CB.util.ent(rng, 1, total);
  return {
    formato: 'teclado',
    consigna: 'Mira la fila. ¿Qué posición ocupa la vagoneta marcada con la ' +
              'estrella, contando desde la izquierda?',
    visual: { tipo: 'fila', total: total, marcada: pos },
    respuesta: pos,
    expr: 'k1_' + total + '_' + pos,
    diagnostico: true
  };
};

/* K2 La casilla de la cuadrícula (2.º) */
CB.gen.espacio.K2 = function (rng, D) {
  const celdas = cuadriculaDeLetras(rng, 3, 3);
  const cc = CB.util.ent(rng, 1, 3);
  const fc = CB.util.ent(rng, 1, 3);
  const resp = celdas[fc - 1][cc - 1];
  const invertida = (cc !== fc) ? celdas[cc - 1][fc - 1] : null;
  return {
    formato: 'opciones4',
    consigna: 'Mira la cuadrícula. ¿Qué letra está en la columna ' + cc +
              ' y en la fila ' + fc + '? La fila 1 es la de abajo.',
    visual: { tipo: 'cuadricula', celdas: celdas },
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: fijosDeLetras(rng, celdas, resp, invertida),
    /* El expr lleva la cuadrícula ENTERA: dos cuadrículas distintas jamás
       comparten identidad (la auditoría severa de 3.4.0 cazó que solo la
       fila 1 no basta: el anti-repetición trataría como iguales dos ítems
       con respuestas distintas). */
    expr: 'k2_' + cc + '_' + fc + '_' + celdas.map(function (f) { return f.join(''); }).join(''),
    diagnostico: false
  };
};

/* K3 Los ejes de simetría (3.º) */
CB.gen.espacio.K3 = function (rng, D) {
  const s = SIMETRIAS_FIGURA[CB.util.ent(rng, 0, (D === 1) ? 1 : 3)];
  return {
    formato: 'teclado',
    consigna: 'Piensa en ' + s[0] + '. ¿Cuántos ejes de simetría tiene?',
    respuesta: s[1],
    expr: 'k3_' + s[1] + '_' + s[0].replace(/[ ,]/g, ''),
    diagnostico: true
  };
};

/* K4 La casilla (columna, fila) (4.º): la notación entre paréntesis. */
CB.gen.espacio.K4 = function (rng, D) {
  const celdas = cuadriculaDeLetras(rng, 4, 3);
  const cc = CB.util.ent(rng, 1, 4);
  const fc = CB.util.ent(rng, 1, 3);
  const resp = celdas[fc - 1][cc - 1];
  const invertida = (cc !== fc && fc <= 4 && cc <= 3) ? celdas[cc - 1][fc - 1] : null;
  return {
    formato: 'opciones4',
    consigna: 'En la casilla (' + cc + ', ' + fc + ') se dice primero la ' +
              'columna y después la fila, y la fila 1 es la de abajo. ' +
              '¿Qué letra hay en esa casilla?',
    visual: { tipo: 'cuadricula', celdas: celdas },
    respuesta: resp,
    respuestaFraccion: true,
    distractoresFijos: fijosDeLetras(rng, celdas, resp, invertida),
    expr: 'k4_' + cc + '_' + fc + '_' + celdas.map(function (f) { return f.join(''); }).join(''),
    diagnostico: false
  };
};

/* K5 El punto del plano (5.º): cuatro puntos con nombre y uno preguntado por
   sus coordenadas. El punto de coordenadas invertidas SIEMPRE está en el
   plano: es el distractor que enseña. */
CB.gen.espacio.K5 = function (rng, D) {
  const tam = 5;
  const x = CB.util.ent(rng, 1, tam);
  let y = CB.util.ent(rng, 1, tam - 1);
  if (y >= x) y += 1;                       /* y ≠ x, sin bucles de rechazo */
  const celdas = [];
  let f, c;
  for (f = 0; f < tam; f++) {
    const fila = [];
    for (c = 0; c < tam; c++) fila.push('');
    celdas.push(fila);
  }
  const etiquetas = CB.util.barajar(['A', 'B', 'C', 'D'], rng);
  celdas[y - 1][x - 1] = etiquetas[0];      /* el preguntado, en (x, y) */
  celdas[x - 1][y - 1] = etiquetas[1];      /* el de coordenadas invertidas */
  /* Dos puntos más en casillas libres, deterministas desde el rng. */
  let puestos = 2, intento;
  for (intento = 0; intento < 40 && puestos < 4; intento++) {
    const cx = CB.util.ent(rng, 1, tam);
    const cy = CB.util.ent(rng, 1, tam);
    if (!celdas[cy - 1][cx - 1]) {
      celdas[cy - 1][cx - 1] = etiquetas[puestos];
      puestos++;
    }
  }
  if (puestos < 4) {                        /* cota alcanzada: relleno fijo */
    for (f = 0; f < tam && puestos < 4; f++) {
      for (c = 0; c < tam && puestos < 4; c++) {
        if (!celdas[f][c]) { celdas[f][c] = etiquetas[puestos]; puestos++; }
      }
    }
  }
  return {
    formato: 'opciones4',
    consigna: 'En el plano se dice primero la columna y después la fila, y ' +
              'la fila 1 es la de abajo. ¿Qué punto está en la casilla (' +
              x + ', ' + y + ')?',
    visual: { tipo: 'cuadricula', celdas: celdas },
    respuesta: etiquetas[0],
    respuestaFraccion: true,
    distractoresFijos: [etiquetas[1], etiquetas[2], etiquetas[3]],
    expr: 'k5_' + x + '_' + y + '_' + celdas.map(function (f) { return f.map(function (l) { return l || '-'; }).join(''); }).join(''),
    diagnostico: false
  };
};

/* K6 La traslación del punto (6.º) */
CB.gen.espacio.K6 = function (rng, D) {
  const d = CB.util.ent(rng, 2, 6);
  const y = CB.util.ent(rng, 1, 9);
  const modo = (D === 1) ? 1 : CB.util.ent(rng, 1, 3);
  if (modo === 1) {
    const x = CB.util.ent(rng, 1, 9);
    return {
      formato: 'teclado',
      consigna: 'El punto (' + x + ', ' + y + ') se mueve ' + d +
                ' casillas a la derecha. ¿En qué columna (el primer número) queda?',
      respuesta: x + d,
      coordenadaInicial: x,
      desplazamiento: d,
      expr: 'k6a_' + x + '_' + y + '_' + d,
      diagnostico: true
    };
  }
  if (modo === 2) {
    const x = CB.util.ent(rng, 1, 9);
    return {
      formato: 'teclado',
      consigna: 'El punto (' + x + ', ' + y + ') se mueve ' + d +
                ' casillas hacia arriba. ¿En qué fila (el segundo número) queda?',
      respuesta: y + d,
      coordenadaInicial: y,
      desplazamiento: d,
      expr: 'k6b_' + x + '_' + y + '_' + d,
      diagnostico: true
    };
  }
  const x = CB.util.ent(rng, d + 1, 12);
  return {
    formato: 'teclado',
    consigna: 'El punto (' + x + ', ' + y + ') se mueve ' + d +
              ' casillas a la izquierda. ¿En qué columna (el primer número) queda?',
    respuesta: x - d,
    expr: 'k6c_' + x + '_' + y + '_' + d,
    diagnostico: true
  };
};

